if(window.pdfjsLib){pdfjsLib.GlobalWorkerOptions.workerSrc="https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js";}
/* ============ ESTADO (persistido en el servidor) ============ */
const uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,7);
function blank(){return{version:2,profesor:{nombre:""},grupos:[],alumnos:[],instrumentos:[],calificaciones:[],incidencias:[],notaObs:{},examenes:[],familias:{},entrevistas:[],agenda:[],partesLeidos:{},notasPrivadas:{},infoProfes:{},notasExamen:{},comedor:{},intereval:{"1":{},"2":{},"3":{}},pendientes:{}}}
// Completa campos que puedan faltar (copias antiguas, versiones previas del formato, etc.)
function normalize(d){
  if(!d||!d.version)return blank();
  if(!d.notaObs)d.notaObs={};if(!d.examenes)d.examenes=[];if(!d.familias)d.familias={};if(!d.entrevistas)d.entrevistas=[];if(!d.agenda)d.agenda=[];
  if(!d.partesLeidos)d.partesLeidos={};
  if(!d.notasPrivadas)d.notasPrivadas={};
  if(!d.infoProfes)d.infoProfes={};
  if(!d.notasExamen)d.notasExamen={};if(!d.pendientes)d.pendientes={};if(!d.comedor)d.comedor={};else{const MESES=["Septiembre","Octubre","Noviembre","Diciembre","Enero","Febrero","Marzo","Abril","Mayo","Junio"];if(Object.keys(d.comedor).some(k=>MESES.includes(k)))d.comedor={};}if(!d.intereval){d.intereval={"1":{},"2":{},"3":{}};}else if(typeof d.intereval==="object"&&!d.intereval["1"]){const old=d.intereval;d.intereval={"1":{},"2":{},"3":{}};Object.entries(old).forEach(([k,v])=>{if(typeof v==="number")d.intereval["1"][k]=v;});}
  // limpiar citas de agenda con fecha pasada
  const ahora=new Date().toISOString().slice(0,16);
  d.agenda=d.agenda.filter(c=>(c.fecha||"")>=ahora);
  return d;
}
let state=blank();
let route={view:"inicio",grupoId:null,tab:"alumnos",alumnoId:null};
// Curso activo (el que se edita) vs. modo archivo (lectura de un curso pasado)
let currentCourseId=null,currentCourseLabel="",readonly=false,liveState=null,liveCourseId=null,liveCourseLabel="";
let _saveTimer=null;
function save(){
  if(readonly){toast("Estás viendo un curso archivado (solo lectura): los cambios no se guardan");return}
  clearTimeout(_saveTimer);
  _saveTimer=setTimeout(()=>{
    fetch("/api/course/active",{method:"PUT",headers:{"Content-Type":"application/json"},body:JSON.stringify(state)})
      .catch(()=>toast("No se pudo guardar en el servidor"));
  },400);
}
async function initApp(){
  try{
    const r=await fetch("/api/course/active");
    if(!r.ok)throw new Error("http "+r.status);
    const j=await r.json();
    currentCourseId=j.id;currentCourseLabel=j.label;
    state=normalize(j.data);
  }catch(e){
    console.error(e);
    state=blank();
    toast("No se pudo conectar con el servidor. Comprueba tu conexión.");
  }
  render();
}
function obsKey(aid,sid,ev){return aid+"|"+sid+"|"+ev}
function getObs(aid,sid,ev){return (state.notaObs&&state.notaObs[obsKey(aid,sid,ev)])||""}
function setObs(aid,sid,ev,txt){if(!state.notaObs)state.notaObs={};const k=obsKey(aid,sid,ev);if(txt&&txt.trim())state.notaObs[k]=txt.trim();else delete state.notaObs[k];save()}

/* ============ HELPERS ============ */
const $=s=>document.querySelector(s);
const esc=s=>(s==null?"":String(s)).replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
// genera un literal JS seguro para usar DENTRO de un atributo onclick="..." (entre comillas dobles)
const jsStr=s=>"'"+String(s==null?"":s).replace(/\\/g,"\\\\").replace(/'/g,"\\'").replace(/&/g,"&amp;").replace(/"/g,"&quot;").replace(/</g,"&lt;").replace(/>/g,"&gt;")+"'";
const fmtDate=d=>new Date(d).toLocaleDateString("es-ES",{day:"2-digit",month:"short",year:"numeric"});
const initials=n=>(n||"?").trim().split(/\s+/).map(w=>w[0]).slice(0,2).join("").toUpperCase();
const EVALS=["1","2","3","FPG","F","E"];
const evalLabel=e=>({"I1":"1ª Inter","I2":"2ª Inter","I3":"3ª Inter","1":"1ª Eval.","2":"2ª Eval.","3":"3ª Eval.","FPG":"Eval. Final PG","F":"Final","E":"Extraord."}[e]||e);
const evalLabelLong=e=>({"1":"1ª evaluación","2":"2ª evaluación","3":"3ª evaluación","FPG":"Evaluación Final Pre Global","F":"Evaluación final","E":"Convocatoria extraordinaria"}[e]||e);

function alumnosDe(gid){return state.alumnos.filter(a=>a.grupoId===gid).sort((a,b)=>((a.apellidos||"")+a.nombre).localeCompare((b.apellidos||"")+b.nombre,"es"))}
function instrumentosDe(gid){return state.instrumentos.filter(i=>i.grupoId===gid).sort((a,b)=>(a.orden||0)-(b.orden||0))}
function incidenciasDe(aid){return state.incidencias.filter(i=>i.alumnoId===aid).sort((a,b)=>b.fecha.localeCompare(a.fecha))}
function notaDe(aid,iid){const c=state.calificaciones.find(c=>c.alumnoId===aid&&c.instrumentoId===iid);return c?c.valor:null}
function media(aid,gid){const ins=instrumentosDe(gid);let sumP=0,acc=0;ins.forEach(i=>{const n=notaDe(aid,i.id);if(n!==null&&n!==""){const p=Number(i.peso)||0;sumP+=p;acc+=Number(n)*p}});if(sumP===0)return null;return Math.round((acc/sumP)*100)/100}
function setNota(aid,iid,val){let c=state.calificaciones.find(c=>c.alumnoId===aid&&c.instrumentoId===iid);if(val===""||val===null){if(c)state.calificaciones=state.calificaciones.filter(x=>x!==c)}else{if(c)c.valor=Number(val);else state.calificaciones.push({id:uid(),alumnoId:aid,instrumentoId:iid,valor:Number(val)})}save()}

/* --- octavilla data en grupo: g.oct = {subjects:[{id,nombre}], data:{ "3":{ matricula:{media,susp,faltas,notas:{subjId:{n,lbl}}} } }, evalsPresentes:[...] } --- */
function octEvals(g){if(!g.oct)return[];return EVALS.filter(e=>g.oct.data&&g.oct.data[e]&&Object.keys(g.oct.data[e]).length);}

function alumnoByMatricula(gid,m){return state.alumnos.find(a=>a.grupoId===gid&&String(a.matricula)===String(m))}
// nota numérica de un alumno (por matrícula) en asignatura/eval
function octNota(g,e,matricula,subjId){
  const d=g.oct&&g.oct.data[e]&&g.oct.data[e][matricula];
  if(d){const c=d.notas[subjId];if(c&&c.n!=null)return c;}
  // En la convocatoria EXTRAORDINARIA, las asignaturas sin nota propia (las que ya estaban
  // aprobadas) se completan con la nota obtenida en la evaluación Final.
  if(e==="E"){
    const df=g.oct&&g.oct.data["F"]&&g.oct.data["F"][matricula];
    if(df){const cf=df.notas[subjId];if(cf&&cf.n!=null)return cf;}
  }
  return null;
}
function octMediaAlumno(g,e,matricula){
  const d=g.oct&&g.oct.data[e]&&g.oct.data[e][matricula];
  if(!d)return null;
  // Recalcular la media SOLO con asignaturas computables (sin talleres, biblioteca,
  // tutoría, religión ni atención educativa). La nota de esas materias se sigue mostrando.
  if(g.oct.subjects){
    const ns=[];
    g.oct.subjects.forEach(s=>{
      if(esExcluidaDeMedia(s.nombre))return;
      const c=octNota(g,e,matricula,s.id); // en extraordinaria completa con la Final
      if(c&&c.n!=null)ns.push(c.n);
    });
    if(ns.length)return Math.round(ns.reduce((a,b)=>a+b,0)/ns.length*100)/100;
    return null;
  }
  return d.media!=null?d.media:null;
}
// Nota de un alumno en una asignatura: para una evaluación, o promediando "todas" las disponibles
function notaAlumnoSubj(g,ev,matricula,subjId){
  if(ev==="all"){
    const vals=[];octEvals(g).forEach(e=>{const c=octNota(g,e,matricula,subjId);if(c&&c.n!=null)vals.push(c.n)});
    return vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:null;
  }
  const c=octNota(g,ev,matricula,subjId);return c&&c.n!=null?c.n:null;
}
// Media de la clase en una asignatura: para una evaluación, o promediando "todas"
function mediaClaseSubj(g,ev,subjId){
  const evs=ev==="all"?octEvals(g):[ev];
  const notas=[];
  alumnosDe(g.id).forEach(a=>{evs.forEach(e=>{const c=octNota(g,e,a.matricula,a&&subjId);if(c&&c.n!=null)notas.push(c.n)})});
  return notas.length?notas.reduce((a,b)=>a+b,0)/notas.length:null;
}
// Media global (todas las asignaturas) de un alumno: para una eval o promediando todas
function mediaGlobalAlumno(g,ev,matricula){
  if(ev==="all"){const vals=[];octEvals(g).forEach(e=>{const m=octMediaAlumno(g,e,matricula);if(m!=null)vals.push(m)});return vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:null}
  return octMediaAlumno(g,ev,matricula);
}
// Media global de la clase: para una eval o promediando todas
function mediaGlobalClase(g,ev){
  const evs=ev==="all"?octEvals(g):[ev];
  const vals=[];alumnosDe(g.id).forEach(a=>{evs.forEach(e=>{const m=octMediaAlumno(g,e,a.matricula);if(m!=null)vals.push(m)})});
  return vals.length?vals.reduce((a,b)=>a+b,0)/vals.length:null;
}

function toast(msg){const t=$("#toast");t.textContent=msg;t.classList.add("show");clearTimeout(t._t);t._t=setTimeout(()=>t.classList.remove("show"),2400)}
function gradeClass(lbl){if(!lbl||lbl==="X")return"g-x";if(lbl==="MH")return"g-mh";const p=lbl.slice(0,2).toLowerCase();return{"in":"g-in","su":"g-su","bi":"g-bi","nt":"g-nt","sb":"g-sb"}[p]||"g-x"}
function gradeCell(c){if(!c)return`<span class="g g-x">·</span>`;if(c.lbl==="X"||c.n==null)return`<span class="g g-x">X</span>`;const disp=c.lbl==="MH"?"10M":c.n;return`<span class="g ${gradeClass(c.lbl)}">${disp}</span>`}

