/* ============ NAV ============ */
function navHtml(){
  const items=[["inicio","Inicio",I.home],["grupos","Mis grupos",I.groups],["archivo","Archivo",I.doc],["ajustes","Ajustes",I.settings]];
  const active=["grupo","alumno"].includes(route.view)?"grupos":route.view;
  return `<div class="brand"><div class="brand-mark">A</div><div><div class="brand-name">Aula Pasteur</div><div class="brand-sub">Gestión docente</div></div></div>
  <div style="display:flex;justify-content:center;padding:0 8px 18px;margin-top:-4px"><img src="data:image/png;base64," alt="Escudo Colegio Pasteur" style="width:72px;height:72px;object-fit:contain;filter:drop-shadow(0 2px 6px rgba(0,0,0,.18))"></div>
  <nav class="nav">${items.map(([k,l,ic])=>`<button class="nav-item ${active===k?"active":""}" onclick="go('${k}')">${ic}<span>${l}</span></button>`).join("")}</nav>
  <div class="nav-spacer"></div>
  <div class="nav-foot">${readonly?`<button onclick="volverAlCursoActual()" style="color:#fff;font-weight:700;text-decoration:underline">← Volver al curso actual</button><br><span style="opacity:.85">Modo archivo (solo lectura): ${esc(currentCourseLabel)}</span>`:`${state.profesor.nombre?esc(state.profesor.nombre)+" · ":""}${esc(currentCourseLabel)}`}</div>`;
}
function renderNav(){$("#sidebar").innerHTML=navHtml();$("#drawerNav").innerHTML=navHtml()}
function openDrawer(){$("#drawer").classList.add("show")}
function closeDrawer(){$("#drawer").classList.remove("show")}
function go(view,opts={}){route={...route,view,...opts};if(view!=="grupo"&&view!=="alumno"){route.grupoId=opts.grupoId??null}route.incOpen=null;route.grpMenu=false;closeDrawer();render()}

/* ============ RENDER ============ */
function render(){
  renderNav();
  const v=route.view;
  if(v==="inicio")viewInicio();else if(v==="grupos")viewGrupos();else if(v==="grupo")viewGrupo();
  else if(v==="alumno")viewAlumno();else if(v==="incidencias")viewIncidencias();else if(v==="ajustes")viewAjustes();
  else if(v==="incTipo")viewIncTipo();
  else if(v==="examenAlumno")viewExamenAlumno();
  else if(v==="examenDetalle")viewExamenDetalle();
  else if(v==="entrevistas")viewEntrevistas();
  else if(v==="archivo")viewArchivo();
  window.scrollTo(0,0);
}

function viewInicio(){
  const nAl=state.alumnos.length,nGr=state.grupos.length;
  const recientes=[...state.incidencias].sort((a,b)=>b.fecha.localeCompare(a.fecha)).slice(0,5);
  const saludo=state.profesor.nombre?`Hola, ${esc(state.profesor.nombre.split(" ")[0])}`:"Tu panel docente";
  let h=`<div class="page-head"><div><h1 class="page-title">${saludo}</h1><div class="page-sub">Resumen de tu actividad</div></div>
    <button class="btn btn-primary" onclick="modalGrupo()">${I.plus}Nuevo grupo</button></div>`;
  h+=`<div class="stat-grid">
    <div class="stat s1"><div class="stat-num">${nGr}</div><div class="stat-lbl">Grupos</div></div>
    <div class="stat s2"><div class="stat-num">${nAl}</div><div class="stat-lbl">Alumnos</div></div>
    <div class="stat s3"><div class="stat-num">${state.grupos.filter(g=>g.esTutoria).length}</div><div class="stat-lbl">Tutorías</div></div>
    <div class="stat s4"><div class="stat-num">${state.incidencias.length}</div><div class="stat-lbl">Incidencias</div></div></div>`;
  h+=`<div class="section-title">Mis grupos</div>`;
  h+=state.grupos.length?`<div class="grid-cards">${state.grupos.map(grupoCard).join("")}</div>`:emptyBlock(I.groups,"Aún no tienes grupos","Crea tu primer grupo (una clase, una asignatura, tu tutoría…) para empezar.",`<button class="btn btn-primary" onclick="modalGrupo()">${I.plus}Crear grupo</button>`);
  $("#view").innerHTML=h;
}
function grupoCard(g){
  const nAl=alumnosDe(g.id).length;
  const extra=g.esTutoria?`${octEvals(g).length} evaluaciones`:`${instrumentosDe(g.id).length} instrumentos`;
  const extraN=g.esTutoria?octEvals(g).length:instrumentosDe(g.id).length;
  return `<button class="group-card" onclick="go('grupo',{grupoId:'${g.id}',tab:'${g.esTutoria?"resumen":"alumnos"}'})">
    <span class="tag ${g.esTutoria?"tag-tut":"tag-mat"}">${g.esTutoria?"Tutoría":esc(g.asignatura||"Materia")}</span>
    <h3>${esc(g.nombre)}</h3><div class="gc-sub">${esc(g.nivel||"")}</div>
    <div class="gc-meta"><div><strong>${nAl}</strong>alumnos</div><div><strong>${extraN}</strong>${g.esTutoria?"evaluaciones":"instrumentos"}</div></div></button>`;
}
function viewGrupos(){
  let h=`<div class="page-head"><div><h1 class="page-title">Mis grupos</h1><div class="page-sub">Clases, asignaturas y tutorías</div></div>
    <button class="btn btn-primary" onclick="modalGrupo()">${I.plus}Nuevo grupo</button></div>`;
  h+=state.grupos.length?`<div class="grid-cards">${state.grupos.map(grupoCard).join("")}</div>`:emptyBlock(I.groups,"Aún no tienes grupos","Crea tu primer grupo para empezar.",`<button class="btn btn-primary" onclick="modalGrupo()">${I.plus}Crear grupo</button>`);
  $("#view").innerHTML=h;
}

/* ---------- VISTA GRUPO ---------- */
function viewGrupo(){
  const g=state.grupos.find(x=>x.id===route.grupoId);
  if(!g){go("grupos");return}
  const tab=route.tab||(g.esTutoria?"resumen":"alumnos");
  let h=`<div class="crumb"><button onclick="go('grupos')">Mis grupos</button> / ${esc(g.nombre)}</div>
  <div class="page-head"><div><h1 class="page-title">${esc(g.nombre)}</h1>
    <div class="page-sub">${g.esTutoria?"Tutoría":esc(g.asignatura||"")} ${g.nivel?"· "+esc(g.nivel):""}</div></div>
    <div style="display:flex;gap:8px;align-items:center">
    <button class="btn btn-ghost btn-sm" onclick="modalGrupo('${g.id}')">${I.edit}Editar</button>
    <div style="position:relative">
      <button class="icon-btn" title="Más opciones" onclick="event.stopPropagation();route.grpMenu=!route.grpMenu;rerenderKeepScroll()">${I.dots}</button>
      ${route.grpMenu?`<div class="pop" style="right:0">
        <button onclick="route.grpMenu=false;modalGrupo('${g.id}')">Editar grupo</button>
        <button class="danger" onclick="route.grpMenu=false;delGrupo('${g.id}')">Eliminar grupo</button>
      </div>`:""}
    </div></div></div>`;
  const tabs=g.esTutoria
    ?[["resumen","Resumen"],["alumnos","Alumnos"],["comparar","Comparar"],["examenes","Exámenes"],["estadisticas","Estadísticas"],["incidencias","Incidencias"],["diplomas","Diplomas"],["familias","Datos Familiares"],...(g.esESO!==false?[["comedor","Comedor"]]:[])]
    :[["alumnos","Alumnos"],["notas","Notas"],["incidencias","Incidencias"]];
  h+=`<div class="tabs">${tabs.map(([k,l])=>`<button class="tab ${tab===k?"active":""}" onclick="go('grupo',{grupoId:'${g.id}',tab:'${k}'})">${l}</button>`).join("")}</div>`;
  if(tab==="alumnos")h+=g.esTutoria?tabAlumnosTut(g):tabAlumnos(g);
  else if(tab==="notas")h+=tabNotas(g);
  else if(tab==="resumen")h+=tabResumen(g);
  else if(tab==="estadisticas")h+=tabEstadisticas(g);
  else if(tab==="comparar")h+=tabComparar(g);
  else if(tab==="examenes")h+=tabExamenes(g);
  else if(tab==="diplomas")h+=tabDiplomas(g);
  else if(tab==="familias")h+=tabFamilias(g);
  else if(tab==="comedor")h+=tabComedor(g);
  else h+=tabIncidenciasGrupo(g);
  $("#view").innerHTML=h;
}

function tabAlumnos(g){
  const als=alumnosDe(g.id);
  let h=`<div style="display:flex;gap:8px;margin-bottom:16px;flex-wrap:wrap">
    <button class="btn btn-primary btn-sm" onclick="modalAlumno('${g.id}')">${I.plus}Añadir alumno</button>
    <button class="btn btn-ghost btn-sm" onclick="modalAlumnosBulk('${g.id}')">${I.users}Añadir varios (lista)</button>
    <button class="btn btn-ghost btn-sm" onclick="importExcelNotas('${g.id}')">${I.upload}Notas exámenes</button></div>`;
  if(!als.length)return h+emptyBlock(I.users,"Sin alumnos","Añade alumnos uno a uno o pega una lista completa de nombres.","");
  h+=`<div class="tbl-wrap"><table><thead><tr><th>Alumno/a</th><th class="num">Media</th><th class="num">Incidencias</th><th></th></tr></thead><tbody>`;
  als.forEach(a=>{const m=media(a.id,g.id);const ni=incidenciasDe(a.id).length;
    h+=`<tr><td class="name-cell" onclick="go('alumno',{alumnoId:'${a.id}',grupoId:'${g.id}'})">${esc(a.apellidos)}, ${esc(a.nombre)}</td>
      <td class="num">${mediaChip(m)}</td><td class="num">${ni?`<span style="font-weight:600">${ni}</span>`:`<span style="color:var(--ink-soft)">—</span>`}</td>
      <td class="num"><button class="icon-btn" onclick="modalAlumno('${g.id}','${a.id}')">${I.edit}</button></td></tr>`;});
  h+=`</tbody></table></div>`;return h;
}
function tabAlumnosTut(g){
  const als=alumnosDe(g.id);const evs=evalsConIntereval(g);const last=evs.filter(e=>!/^I/.test(e)).slice(-1)[0];
  let h=`<div style="display:flex;gap:8px;margin-bottom:16px;flex-wrap:wrap">
    <button class="btn btn-primary btn-sm" onclick="importOctavilla('${g.id}')">${I.upload}Añadir octavilla</button>
    <button class="btn btn-ghost btn-sm" onclick="importExcelNotas('${g.id}')">${I.upload}Notas exámenes</button>
    <button class="btn btn-ghost btn-sm" onclick="importAlumnosExcel('${g.id}')">${I.upload}Subir Excel de alumnos</button>
    <button class="btn btn-ghost btn-sm" onclick="importInfoAlumnos('${g.id}')">${I.upload}Añadir información de alumnos</button>
    <button class="btn btn-ghost btn-sm" onclick="importarPendientes('${g.id}')">${I.upload}Importar A. Pendientes</button>
    ${g.esESO!==false?`<button class="btn btn-ghost btn-sm" onclick="importarInterevaluacion()">${I.upload}Interevaluación</button>`:""}
    ${(octEvals(g).length||(g.esESO!==false&&state.intereval&&["1","2","3"].some(t=>state.intereval[t]&&alumnosDe(g.id).some(a=>state.intereval[t][a.matricula]!=null))))?`<button class="btn btn-ghost btn-sm" onclick="modalBorrarEval('${g.id}')" style="color:var(--clay)"><svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2" width="15" height="15"><polyline points="5,5 15,5"/><rect x="6" y="7" width="8" height="9" rx="1"/><line x1="8" y1="9" x2="8" y2="14"/><line x1="12" y1="9" x2="12" y2="14"/></svg>Borrar evaluación</button>`:""}
    <button class="btn btn-ghost btn-sm" onclick="modalAlumno('${g.id}')">${I.plus}Añadir alumno</button></div>`;
  if(!als.length)return h+emptyBlock(I.upload,"Aún no hay alumnos","Si ya tienes la octavilla del trimestre, súbela y se cargarán los alumnos con sus notas. Si es comienzo de curso, sube el Excel con la lista de la clase. También puedes añadirlos a mano.","");
  h+=`<div class="tbl-wrap"><table><thead><tr><th>Nº</th><th>Alumno/a</th>${evs.map(e=>"<th class=\"num\""+(/^I/.test(e)?" style=\"color:var(--navy);font-style:italic\"":" ")+">"+evalLabel(e)+"</th>").join("")}<th></th></tr></thead><tbody>`;
  als.forEach((a,i)=>{
    h+=`<tr><td class="num" style="color:var(--ink-soft)">${i+1}</td>
      <td class="name-cell" onclick="go('alumno',{alumnoId:'${a.id}',grupoId:'${g.id}'})">${esc(a.apellidos)}, ${esc(a.nombre)}</td>
      ${evs.map(e=>/^I/.test(e)?ieResumenCell(g,e,a.matricula):`<td class="num cmp-cell">${mediaChip(octMediaAlumno(g,e,a.matricula))}<span class="susp-abs">${suspMini(octSuspAlumno(g,e,a.matricula))}</span></td>`).join("")}
      <td class="num"><button class="icon-btn" onclick="modalAlumno('${g.id}','${a.id}')">${I.edit}</button></td></tr>`;});
  h+=`</tbody></table></div>`;return h;
}
function mediaChip(m){if(m===null||m===undefined)return`<span class="media-chip m-none">—</span>`;return`<span class="media-chip ${m>=5?"m-pass":"m-fail"}">${Number(m).toFixed(2)}</span>`}
function tabResumen(g){
  const evs=octEvals(g);const als=alumnosDe(g.id);
  if(!evs.length)return emptyBlock(I.upload,"Aún no hay datos de evaluación","Importa una octavilla para ver aquí el resumen de la clase: medias, aprobados y la evolución del grupo.",`<button class="btn btn-primary" onclick="importOctavilla('${g.id}')">${I.upload}Añadir octavilla</button>`);
  const sel=route.resEval&&evs.includes(route.resEval)?route.resEval:evs[evs.length-1];
  const suspDe=a=>{const d=g.oct.data[sel]&&g.oct.data[sel][a.matricula];return d&&d.susp!=null?d.susp:null};
  let medias=[],susp=0,total=0;
  als.forEach(a=>{const m=octMediaAlumno(g,sel,a.matricula);if(m!=null){medias.push(m);total++;if(m<5)susp++}});
  const mediaClase=medias.length?(medias.reduce((s,x)=>s+x,0)/medias.length):null;
  let h=`<div style="display:flex;align-items:center;gap:12px;margin-bottom:18px;flex-wrap:wrap">
    <span style="font-weight:600;font-size:14px">Evaluación:</span>
    <div class="seg">${evs.map(e=>`<button class="${e===sel?"on":""}" onclick="route.resEval='${e}';rerenderKeepScroll()">${evalLabel(e)}</button>`).join("")}</div>
    <button class="btn btn-green btn-sm" style="margin-left:auto" onclick="generarActa('${g.id}','${sel}')">${I.doc}Generar acta (${evalLabel(sel)})</button></div>`;
  h+=`<div class="stat-grid">
    <div class="stat s2"><div class="stat-num">${als.length}</div><div class="stat-lbl">Alumnos</div></div>
    <div class="stat s1"><div class="stat-num">${mediaClase!=null?mediaClase.toFixed(2):"—"}</div><div class="stat-lbl">Media de clase</div></div>
    <div class="stat s3"><div class="stat-num">${total-susp}</div><div class="stat-lbl">Con media aprobada</div></div>
    <div class="stat s4"><div class="stat-num">${susp}</div><div class="stat-lbl">Con media insuficiente</div></div></div>`;
  const conSusp=als.map(suspDe).filter(v=>v!=null);
  const baseN=conSusp.length;
  const b0=conSusp.filter(s=>s===0).length,b12=conSusp.filter(s=>s>=1&&s<=2).length,b3=conSusp.filter(s=>s===3).length,b4=conSusp.filter(s=>s>=4).length;
  const pct=n=>baseN?Math.round(n/baseN*100):0;
  h+=`<div class="panel" style="margin-bottom:20px"><h3>Asignaturas suspensas por alumno · ${evalLabel(sel)}</h3>
    <div class="dist-grid">
      ${distCard("Ninguna suspensa",b0,pct(b0),"var(--green)")}
      ${distCard("1 – 2 suspensas",b12,pct(b12),"var(--gold)")}
      ${distCard("3 suspensas",b3,pct(b3),"var(--amber)")}
      ${distCard("4 o más suspensas",b4,pct(b4),"var(--red)")}
    </div>
    ${baseN<als.length?`<p style="font-size:12px;color:var(--ink-soft);margin-top:10px">* Sobre ${baseN} alumnos con dato de suspensos en esta evaluación.</p>`:""}</div>`;
  h+=`<div class="panel" style="margin-bottom:20px"><h3>Evolución de la media de la clase</h3>`;
  const serie=evs.map(e=>{let ms=[];als.forEach(a=>{const m=octMediaAlumno(g,e,a.matricula);if(m!=null)ms.push(m)});return ms.length?ms.reduce((s,x)=>s+x,0)/ms.length:null});
  h+=lineChart(evs.map(evalLabel),serie)+`</div>`;
  const mejores=als.map(a=>({a,m:octMediaAlumno(g,sel,a.matricula)})).filter(x=>x.m!=null).sort((x,y)=>y.m-x.m).slice(0,8);
  const flojos=als.map(a=>({a,m:octMediaAlumno(g,sel,a.matricula),s:suspDe(a)}))
    .filter(x=>x.m!=null&&(x.m<5||(x.s!=null&&x.s>=3)))
    .sort((x,y)=>{const ka=(x.m<5?0:1),kb=(y.m<5?0:1);if(ka!==kb)return ka-kb;return x.m-y.m});
  h+=`<div class="split"><div class="panel"><h3>Mejores notas (${evalLabel(sel)})</h3>`;
  if(!mejores.length)h+=`<p style="color:var(--ink-soft);font-size:14px">Sin datos.</p>`;
  else{h+=`<div style="display:flex;flex-direction:column;gap:8px">`;mejores.forEach(({a,m},i)=>{
    h+=`<div style="display:flex;align-items:center;gap:12px;padding:8px 0;border-bottom:1px dashed var(--line)">
      <span style="width:16px;color:var(--ink-soft);font-weight:700;font-variant-numeric:tabular-nums">${i+1}</span>
      <span class="media-chip m-pass">${m.toFixed(2)}</span>
      <span class="name-cell" style="flex:1" onclick="go('alumno',{alumnoId:'${a.id}',grupoId:'${g.id}'})">${esc(a.apellidos)}, ${esc(a.nombre)}</span></div>`;});h+=`</div>`;}
  h+=`</div><div class="panel"><h3>Alumnos con dificultades (${evalLabel(sel)})</h3>
    <p style="font-size:12px;color:var(--ink-soft);margin:-8px 0 12px">Media inferior a 5, o con 3+ asignaturas suspensas.</p>`;
  if(!flojos.length)h+=`<p style="color:var(--ink-soft);font-size:14px">Ningún alumno en dificultades. 🎉</p>`;
  else{h+=`<div style="display:flex;flex-direction:column;gap:8px">`;flojos.forEach(({a,m,s})=>{
    const okMedia=m>=5;
    h+=`<div style="display:flex;align-items:center;gap:12px;padding:8px 0;border-bottom:1px dashed var(--line)">
      <span class="media-chip ${okMedia?"m-pass":"m-fail"}">${m.toFixed(2)}</span>
      <span class="name-cell" style="flex:1" onclick="go('alumno',{alumnoId:'${a.id}',grupoId:'${g.id}'})">${esc(a.apellidos)}, ${esc(a.nombre)}</span>
      ${s!=null&&s>=3?`<span class="tag-susp">${s} susp.</span>`:""}</div>`;});h+=`</div>`;}
  h+=`</div></div>`;
  return h;
}
function distCard(label,n,pct,color){
  return `<div class="dist"><div class="dist-bar" style="background:${color}"></div><div class="dist-n">${n}</div><div class="dist-l">${label}</div><div class="dist-p">${pct}% de la clase</div></div>`;
}
function tabEstadisticas(g){
  const evs=octEvals(g);
  if(!evs.length)return emptyBlock(I.chart,"Sin datos para estadísticas","Importa al menos una octavilla para ver las medias por asignatura y la dificultad de cada materia.",`<button class="btn btn-primary" onclick="importOctavilla('${g.id}')">${I.upload}Añadir octavilla</button>`);
  const sel=route.statEval&&evs.includes(route.statEval)?route.statEval:evs[evs.length-1];
  let h=`<div style="display:flex;align-items:center;gap:12px;margin-bottom:18px;flex-wrap:wrap">
    <span style="font-weight:600;font-size:14px">Evaluación:</span>
    <div class="seg">${evs.map(e=>`<button class="${e===sel?"on":""}" onclick="route.statEval='${e}';rerenderKeepScroll()">${evalLabel(e)}</button>`).join("")}</div></div>`;
  const subs=g.oct.subjects.filter(s=>!esExcluida(s.nombre));
  const rows=subs.map(s=>{
    let notas=[],ap=0,pres=0;
    alumnosDe(g.id).forEach(a=>{const c=octNota(g,sel,a.matricula,s.id);if(c&&c.n!=null){notas.push(c.n);pres++;if(c.n>=5)ap++}});
    const med=notas.length?notas.reduce((x,y)=>x+y,0)/notas.length:null;
    return{s,med,ap,pres,pct:pres?Math.round(ap/pres*100):null};
  }).filter(r=>r.pres>0).sort((a,b)=>(a.med??99)-(b.med??99));
  h+=`<div class="panel" style="margin-bottom:20px"><h3>Nota media por asignatura · ${evalLabel(sel)}</h3>`;
  rows.forEach(r=>{const col=r.med>=5?"var(--green)":"var(--red)";
    h+=`<div class="barrow"><div class="bl" title="${esc(r.s.nombre)}">${esc(shortSubj(r.s.nombre))}</div>
      <div class="bt"><div class="bf" style="width:${(r.med/10*100).toFixed(0)}%;background:${col}"></div></div>
      <div class="bv">${r.med.toFixed(2)} · ${r.pct}%</div></div>`;});
  h+=`<div class="legend"><span><i style="background:var(--green)"></i>media ≥5</span><span><i style="background:var(--red)"></i>media &lt;5</span><span>· el % es la proporción de aprobados</span></div></div>`;
  const dificiles=[...rows].slice(0,3);
  h+=`<div class="panel"><h3>Lectura rápida</h3>
    <div class="kv"><span>Asignatura con mayor dificultad</span><strong>${dificiles[0]?esc(shortSubj(dificiles[0].s.nombre))+" ("+dificiles[0].med.toFixed(2)+")":"—"}</strong></div>
    <div class="kv"><span>Asignatura con mejor resultado</span><strong>${rows.length?esc(shortSubj(rows[rows.length-1].s.nombre))+" ("+rows[rows.length-1].med.toFixed(2)+")":"—"}</strong></div>
    <div class="kv"><span>Asignaturas con suspensos</span><strong>${rows.filter(r=>r.pct<100).length} de ${rows.length}</strong></div></div>`;
  h+=compararAlumnoClase(g);
  return h;
}
function compararAlumnoClase(g){
  const als=alumnosDe(g.id);
  if(!als.length)return"";
  const evs=octEvals(g);
  const evSel=route.statCmpEval&&(route.statCmpEval==="all"||evs.includes(route.statCmpEval))?route.statCmpEval:evs[evs.length-1];
  const aid=route.statCmpAlumno&&als.some(a=>a.id===route.statCmpAlumno)?route.statCmpAlumno:als[0].id;
  const a=als.find(x=>x.id===aid);
  const subs=g.oct.subjects.filter(s=>!esExcluida(s.nombre));
  const filas=subs.map(s=>{
    const na=notaAlumnoSubj(g,evSel,a.matricula,s.id);
    const mc=mediaClaseSubj(g,evSel,s.id);
    return{nombre:shortSubj(s.nombre),na,mc,d:(na!=null&&mc!=null)?na-mc:null};
  }).filter(r=>r.na!=null);
  const gA=mediaGlobalAlumno(g,evSel,a.matricula), gC=mediaGlobalClase(g,evSel);
  const opEv=evs.map(e=>`<button class="${evSel===e?"on":""}" onclick="route.statCmpEval='${e}';rerenderKeepScroll()">${evalLabel(e)}</button>`).join("")
    +`<button class="${evSel==="all"?"on":""}" onclick="route.statCmpEval='all';rerenderKeepScroll()">Todas juntas</button>`;
  let h=`<div class="panel" style="margin-top:20px"><h3>Comparar un alumno con la clase</h3>
    <div style="display:flex;gap:14px;flex-wrap:wrap;align-items:center;margin-bottom:16px">
      <div style="display:flex;align-items:center;gap:8px"><span style="font-weight:600;font-size:14px">Alumno:</span>
        <select onchange="route.statCmpAlumno=this.value;rerenderKeepScroll()" style="padding:9px 12px;border:1px solid var(--line-2);border-radius:9px;font-size:14px">${als.map(x=>`<option value="${x.id}" ${x.id===aid?"selected":""}>${esc(x.apellidos)}, ${esc(x.nombre)}</option>`).join("")}</select></div>
      <div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap"><span style="font-weight:600;font-size:14px">Periodo:</span><div class="seg">${opEv}</div></div>
    </div>`;
  const dG=(gA!=null&&gC!=null)?gA-gC:null;
  h+=`<div class="cmp-global">
    <div class="cmp-g-item"><div class="cmp-g-lbl">Media de ${esc(a.nombre)}</div><div class="cmp-g-val" style="color:${gA!=null&&gA>=5?"var(--green)":"var(--red)"}">${gA!=null?gA.toFixed(2):"—"}</div></div>
    <div class="cmp-g-item"><div class="cmp-g-lbl">Media de la clase</div><div class="cmp-g-val">${gC!=null?gC.toFixed(2):"—"}</div></div>
    <div class="cmp-g-item"><div class="cmp-g-lbl">Diferencia</div><div class="cmp-g-val">${deltaBadge(dG)}</div></div>
  </div>`;
  h+=`<div class="tbl-wrap" style="margin-top:16px;box-shadow:none;border:1px solid var(--line)"><table><thead><tr><th>Asignatura</th><th class="num">${esc(a.nombre)}</th><th class="num">Clase</th><th class="num">Diferencia</th></tr></thead><tbody>`;
  filas.forEach(r=>{h+=`<tr><td style="font-weight:600">${esc(r.nombre)}</td><td class="num">${r.na!=null?mediaChip(r.na):"—"}</td><td class="num" style="color:var(--ink-soft)">${r.mc!=null?r.mc.toFixed(2):"—"}</td><td class="num">${deltaBadge(r.d)}</td></tr>`});
  h+=`</tbody></table></div>`;
  h+=`<p style="font-size:12.5px;color:var(--ink-soft);margin-top:10px">La diferencia compara la nota del alumno con la media de esa asignatura en toda la clase. Verde = por encima de la media; rojo = por debajo. «Todas juntas» promedia las evaluaciones disponibles.</p>`;
  h+=`</div>`;
  return h;
}
function tabComparar(g){
  const modo=route.cmpModo||"evs";
  const toggle=`<div class="seg" style="margin-bottom:18px">
    <button class="${modo==="evs"?"on":""}" onclick="route.cmpModo='evs';rerenderKeepScroll()">&#9878; Comparar evaluaciones</button>
    <button class="${modo==="dos"?"on":""}" onclick="route.cmpModo='dos';rerenderKeepScroll()">&#128101; Comparar dos alumnos</button>
  </div>`;
  if(modo==="dos") return toggle+tabCompararDos(g);
  // Incluye interevaluaciones en el orden: I1,1,I2,2,I3,3,...
  const evs=evalsConIntereval(g);
  if(evs.length<2) return toggle+emptyBlock(I.chart,"Necesitas al menos dos evaluaciones","Cuando importes una segunda octavilla (o interevaluación) podrás comparar la evolución de cada alumno.",`<button class="btn btn-primary" onclick="importOctavilla('${g.id}')">${I.upload}Añadir octavilla</button>`);
  const eA=route.cmpA&&evs.includes(route.cmpA)?route.cmpA:evs[evs.length-2];
  const eB=route.cmpB&&evs.includes(route.cmpB)?route.cmpB:evs[evs.length-1];
  const sort=route.cmpSort||"lista";
  const isIE=e=>/^I/.test(e);
  const mixto=(isIE(eA)&&!isIE(eB))||(!isIE(eA)&&isIE(eB));
  const selA="<div class=\"seg\">"+evs.map(e=>"<button class=\""+(e===eA?"on":"")+"\" onclick=\"setCmpA('"+e+"')\">"+evalLabel(e)+"</button>").join("")+"</div>";
  const selB="<div class=\"seg\">"+evs.map(e=>"<button class=\""+(e===eB?"on":"")+"\" onclick=\"setCmpB('"+e+"')\">"+evalLabel(e)+"</button>").join("")+"</div>";
  let h=toggle+`<div style="display:flex;align-items:center;gap:12px;margin-bottom:18px;flex-wrap:wrap">
    <span style="font-weight:600;font-size:14px">De</span>${selA}
    <span style="font-weight:600;font-size:14px">a</span>${selB}</div>`;
  // Valor numérico para mostrar: media si es evaluación, nº NA si es interevaluación
  const valOf=(e,mat)=>{
    if(isIE(e)){
      const t=e[1];const d=state.intereval&&state.intereval[t]&&state.intereval[t][mat];
      if(!d)return null;
      let na=0;if(d.gradesByName&&g.oct){g.oct.subjects.forEach(s=>{if(esExcluida(s.nombre))return;if(ieMatchGrade(d.gradesByName,s.nombre)==="NA")na++;});}else na=d.na||0;
      return na;
    }
    return octMediaAlumno(g,e,mat);
  };
  // Nº de suspensos de un periodo (NA si es interevaluación, suspensos de octavilla si es evaluación)
  const suspOf=(e,mat)=>{
    if(isIE(e)){
      const t=e[1];const d=state.intereval&&state.intereval[t]&&state.intereval[t][mat];
      if(!d)return null;
      let na=0;if(d.gradesByName&&g.oct){g.oct.subjects.forEach(s=>{if(esExcluida(s.nombre))return;if(ieMatchGrade(d.gradesByName,s.nombre)==="NA")na++;});}else na=d.na||0;
      return na;
    }
    return octSuspAlumno(g,e,mat);
  };
  let rows=alumnosDe(g.id).map(a=>{
    const mA=valOf(eA,a.matricula),mB=valOf(eB,a.matricula);
    // delta: si ambos son del mismo tipo. Para IE menor NA es mejor → invertimos signo
    let d=null;       // delta de medias (solo eval vs eval)
    let dSusp=null;   // delta de suspensos (caso mixto IE vs eval)
    if(mA!=null&&mB!=null){
      if(isIE(eA)&&isIE(eB)) d=mA-mB;        // menos NA en B = mejora (positivo)
      else if(!isIE(eA)&&!isIE(eB)) d=mB-mA; // más media en B = mejora
      else{
        // Mixto: diferencia de suspensos (B - A). Negativo = bajaron (mejora)
        const sA=suspOf(eA,a.matricula),sB=suspOf(eB,a.matricula);
        if(sA!=null&&sB!=null) dSusp=sB-sA;
      }
    }
    return{a,mA,mB,d,dSusp};
  });
  if(sort==="mejor") rows=rows.slice().sort((x,y)=>(y.d==null?-Infinity:y.d)-(x.d==null?-Infinity:x.d));
  else if(sort==="peor") rows=rows.slice().sort((x,y)=>(x.d==null?Infinity:x.d)-(y.d==null?Infinity:y.d));
  const sortLbl={lista:"Orden de lista",mejor:"Mejor cambio",peor:"Peor cambio"}[sort];
  const menuPop=route.cmpMenu?`<div class="pop">${[["lista","Orden de lista"],["mejor","Mejor cambio"],["peor","Peor cambio"]].map(([k,l])=>`<button class="${sort===k?"on":""}" onclick="route.cmpSort='${k}';route.cmpMenu=false;rerenderKeepScroll()">${l}</button>`).join("")}</div>`:"";
  h+=`<div class="tbl-wrap"><table><thead><tr>
    <th>Alumno/a</th>
    <th class="num"${isIE(eA)?' style="color:var(--navy);font-style:italic"':""}>${evalLabel(eA)}</th>
    <th class="num"${isIE(eB)?' style="color:var(--navy);font-style:italic"':""}>${evalLabel(eB)}</th>
    <th class="num" style="position:relative;overflow:visible">
      <span class="th-menu" onclick="event.stopPropagation();route.cmpMenu=!route.cmpMenu;rerenderKeepScroll()">Cambio <span style="font-size:10px">&#9662;</span></span>
      ${menuPop}
    </th></tr></thead><tbody>`;
  rows.forEach(function(row){
    var a=row.a,mA=row.mA,mB=row.mB,d=row.d,dSusp=row.dSusp;
    const cA=isIE(eA)?`<td class="num cmp-cell">${ieBadge(mA)}</td>`:`<td class="num cmp-cell">${mediaChip(mA)}<span class="susp-abs">${suspMini(octSuspAlumno(g,eA,a.matricula))}</span></td>`;
    const cB=isIE(eB)?`<td class="num cmp-cell">${ieBadge(mB)}</td>`:`<td class="num cmp-cell">${mediaChip(mB)}<span class="susp-abs">${suspMini(octSuspAlumno(g,eB,a.matricula))}</span></td>`;
    let deltaCell;
    if(mixto){
      deltaCell=`<td class="num">${suspDeltaBadge(dSusp)}</td>`;
    }else{
      deltaCell=d==null?`<td class="num" style="color:var(--ink-soft)">—</td>`:`<td class="num">${deltaBadge(d)}</td>`;
    }
    h+=`<tr><td class="name-cell" onclick="go('alumno',{alumnoId:'${a.id}',grupoId:'${g.id}'})">${esc(a.apellidos)}, ${esc(a.nombre)}</td>
    ${cA}${cB}${deltaCell}</tr>`;
  });
  const nota=mixto?"Comparas una interevaluación con una evaluación: el «Cambio» muestra la diferencia de suspensos (azul = bajaron, rojo = subieron, = igual).":((isIE(eA)||isIE(eB))?"En interevaluaciones se muestra el nº de No Aptos (0 en verde = todo apto).":"El número rojo junto a la nota son las asignaturas suspensas.");
  h+=`</tbody></table></div><div style="font-size:12.5px;color:var(--ink-soft);margin-top:8px">Orden actual: <strong>${sortLbl}</strong> · pulsa «Cambio &#9662;» para cambiarlo. ${nota}</div>`;
  return h;
}


// ─── ASIGNATURAS PENDIENTES ─────────────────────────────────────────────
function importarPendientes(gid){
  if(!window.pdfjsLib){toast("No se pudo cargar el lector de PDF");return;}
  const inp=document.createElement("input");inp.type="file";inp.accept="application/pdf,.pdf";
  inp.onchange=e=>{const f=e.target.files[0];if(f)procesarPendientesPDF(f,gid);};inp.click();
}
function procesarPendientesPDF(file,gid){
  openModalCls(`<div class="modal-head"><h2>Leyendo pendientes…</h2></div><div class="modal-body" style="text-align:center;padding:40px 24px"><div class="spinner"></div></div>`,"");
  const fr=new FileReader();
  fr.onload=async()=>{
    try{
      const pdf=await pdfjsLib.getDocument({data:new Uint8Array(fr.result)}).promise;
      const records=[];
      for(let p=1;p<=pdf.numPages;p++){
        const page=await pdf.getPage(p);
        const vp=page.getViewport({scale:1});
        const tc=await page.getTextContent();
        const items=tc.items.map(it=>({s:it.str.trim(),x:it.transform[4],y:vp.height-it.transform[5]})).filter(it=>it.s);
        parsePendientesPage(items,records,gid);
      }
      if(!records.length){closeModal();toast("No encontré asignaturas pendientes en ese PDF");return;}
      // Mostrar preview y confirmar
      window._pendRecords=records;
      const rows=records.map(r=>`<tr><td>${esc(r.nombre)}</td><td>${esc(r.materia)}</td><td>${esc(r.curso)}</td></tr>`).join("");
      openModalCls(`<div class="modal-head"><h2>Confirmar importación</h2></div>
        <div class="modal-body">
          <p style="margin-bottom:10px">Se encontraron <strong>${records.length} asignatura(s) pendiente(s)</strong>:</p>
          <div style="max-height:320px;overflow-y:auto;border:1px solid var(--line);border-radius:8px">
          <table style="width:100%;font-size:12.5px;border-collapse:collapse">
            <thead><tr style="background:var(--paper-2)"><th style="padding:6px 10px;text-align:left">Alumno/a</th><th style="padding:6px 10px;text-align:left">Asignatura</th><th style="padding:6px 10px;text-align:left">Curso</th></tr></thead>
            <tbody>${rows}</tbody>
          </table></div>
          <div style="display:flex;gap:10px;margin-top:16px;justify-content:flex-end">
            <button class="btn btn-ghost" onclick="closeModal()">Cancelar</button>
            <button class="btn btn-primary" onclick="confirmarPendientes()">Guardar</button>
          </div>
        </div>`,"");
    }catch(err){console.error(err);closeModal();toast("Error al leer el PDF: "+(err.message||err));}
  };
  fr.readAsArrayBuffer(file);
}
function parsePendientesPage(items,records,gid){
  // Columnas por x: Nº<35, Nombre 35-150, Materia 150-300, Curso 300-450
  const cursoItems=items.filter(it=>it.x>=300&&it.x<470&&/\dº/.test(it.s)).sort((a,b)=>a.y-b.y);
  const materiaItems=items.filter(it=>it.x>=150&&it.x<300).sort((a,b)=>a.y-b.y);
  const nombreItems=items.filter(it=>it.x>=35&&it.x<150&&/,/.test(it.s)&&it.s.length>5).sort((a,b)=>a.y-b.y);
  const numItems=items.filter(it=>it.x<35&&/^\d+$/.test(it.s)).sort((a,b)=>a.y-b.y);
  // Construir estudiantes
  const students=nombreItems.map((ni,i)=>{
    const num=numItems.find(n=>Math.abs(n.y-ni.y)<8);
    return{y:ni.y,nombre:ni.s,num:num?parseInt(num.s):i+1,asigs:[]};
  });
  if(!students.length)return;
  // Para cada curso, reconstruir la materia buscando textos cercanos en y (±20px)
  cursoItems.forEach(ci=>{
    const parts=materiaItems.filter(m=>Math.abs(m.y-ci.y)<=22).sort((a,b)=>a.y-b.y);
    const materia=parts.map(p=>p.s).join(" ").replace(/\s+/g," ").trim();
    // Asignar al estudiante más cercano en y
    let closest=students[0];let minD=1e9;
    students.forEach(st=>{const d=Math.abs(st.y-ci.y);if(d<minD){minD=d;closest=st;}});
    closest.asigs.push({materia,curso:ci.s});
  });
  // Convertir a registros con nombre de alumno y matchear con alumnos del grupo
  const als=alumnosDe(gid);
  students.forEach(st=>{
    const normN=n=>n.toUpperCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^A-Z\s]/g,"").trim();
    const match=als.find(a=>{
      const fn=normN(a.apellidos+", "+a.nombre);
      const fn2=normN(a.apellidos+" "+a.nombre);
      const sn=normN(st.nombre);
      return fn.includes(sn)||sn.includes(fn)||fn2.includes(sn);
    });
    const alumnoId=match?match.id:null;
    st.asigs.forEach(asig=>{
      records.push({alumnoId,nombre:st.nombre,materia:asig.materia,curso:asig.curso});
    });
  });
}
function confirmarPendientes(){
  const records=window._pendRecords||[];
  if(!state.pendientes)state.pendientes={};
  records.forEach(r=>{
    if(!r.alumnoId)return;
    if(!state.pendientes[r.alumnoId])state.pendientes[r.alumnoId]=[];
    const exists=state.pendientes[r.alumnoId].some(p=>
      p.materia.toLowerCase()===r.materia.toLowerCase()&&p.curso===r.curso);
    if(!exists)state.pendientes[r.alumnoId].push({materia:r.materia,curso:r.curso,aprobada:false,manual:false});
  });
  save();closeModal();rerenderKeepScroll();toast(`Pendientes importadas: ${records.filter(r=>r.alumnoId).length} registradas ✓`);
}
function panelPendientes(a,g){
  const pends=(state.pendientes&&state.pendientes[a.id])||[];
  const formKey="pendForm_"+a.id;
  const formOpen=!!route[formKey];
  let h=`<div class="panel" style="margin-bottom:18px">
    <div style="display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:${pends.length||formOpen?"14px":"0"}">
      <h3 style="margin:0">📚 Asignaturas pendientes de años anteriores</h3>
      <div style="display:flex;gap:6px;flex-shrink:0">
        <button class="btn btn-ghost btn-sm" onclick="route['${formKey}']=!route['${formKey}'];rerenderKeepScroll()">
          ${formOpen?`<svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2" width="16" height="16"><line x1="5" y1="5" x2="15" y2="15"/><line x1="15" y1="5" x2="5" y2="15"/></svg> Cerrar`:`${I.plus}Añadir`}
        </button>
      </div>
    </div>`;
  if(formOpen){
    const fMat=route[formKey+"_mat"]||"";
    const fCur=route[formKey+"_cur"]||"";
    h+=`<div style="background:var(--paper-2);border:1px solid var(--line-2);border-radius:12px;padding:14px 16px;margin-bottom:14px;display:grid;grid-template-columns:1fr auto auto;gap:10px;align-items:end">
      <div>
        <label style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.04em;color:var(--ink-soft);display:block;margin-bottom:4px">Asignatura</label>
        <input id="pf_mat_${a.id}" value="${esc(fMat)}" placeholder="Ej. Matemáticas" oninput="route['${formKey}_mat']=this.value" style="width:100%;padding:8px 11px;border:1px solid var(--line-2);border-radius:8px;background:#fff;font-size:13.5px">
      </div>
      <div>
        <label style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.04em;color:var(--ink-soft);display:block;margin-bottom:4px">Curso</label>
        <input id="pf_cur_${a.id}" value="${esc(fCur)}" placeholder="Ej. 3º E.S.O." oninput="route['${formKey}_cur']=this.value" style="width:160px;padding:8px 11px;border:1px solid var(--line-2);border-radius:8px;background:#fff;font-size:13.5px">
      </div>
      <button class="btn btn-primary btn-sm" onclick="guardarPendienteManual('${a.id}','${formKey}')">Añadir</button>
    </div>`;
  }
  if(!pends.length){
    h+=`<p style="color:var(--ink-soft);font-size:13.5px;margin:0">Sin asignaturas pendientes registradas. Importa el PDF de «Listado materias pendientes» de Rayuela o añade una manualmente.</p></div>`;
    return h;
  }
  h+=`<table style="width:100%;border-collapse:collapse;font-size:13px">
    <thead><tr style="background:var(--paper-2);border-bottom:1px solid var(--line)">
      <th style="padding:6px 10px;text-align:left">Asignatura</th>
      <th style="padding:6px 10px;text-align:left">Curso</th>
      <th style="padding:6px 10px;text-align:center">Estado</th>
      <th style="padding:6px 10px;width:32px"></th>
    </tr></thead><tbody>`;
  pends.forEach((p,i)=>{
    h+=`<tr style="border-bottom:1px solid var(--line)">
      <td style="padding:7px 10px">${esc(p.materia)}</td>
      <td style="padding:7px 10px;color:var(--ink-soft)">${esc(p.curso)}</td>
      <td style="padding:7px 10px;text-align:center">
        <button onclick="togglePendienteAprobada('${a.id}',${i})" style="border:none;background:${p.aprobada?'#e8f5e9':'#ffeaea'};color:${p.aprobada?'#2e7d32':'#c0392b'};padding:3px 10px;border-radius:20px;font-size:11.5px;font-weight:700;cursor:pointer">
          ${p.aprobada?'✓ Superada':'✗ Pendiente'}
        </button>
      </td>
      <td style="padding:7px 4px;text-align:center">
        <button onclick="eliminarPendiente('${a.id}',${i})" style="background:none;border:none;cursor:pointer;color:var(--ink-soft);opacity:.5;font-size:16px" onmouseover="this.style.opacity=1" onmouseout="this.style.opacity=.5">×</button>
      </td>
    </tr>`;
  });
  h+=`</tbody></table></div>`;
  return h;
}
function guardarPendienteManual(aid,formKey){
  const mat=document.getElementById("pf_mat_"+aid)?.value?.trim()||route[formKey+"_mat"]||"";
  const cur=document.getElementById("pf_cur_"+aid)?.value?.trim()||route[formKey+"_cur"]||"";
  if(!mat){toast("Escribe el nombre de la asignatura");return;}
  if(!state.pendientes)state.pendientes={};
  if(!state.pendientes[aid])state.pendientes[aid]=[];
  state.pendientes[aid].push({materia:mat,curso:cur||"",aprobada:false,manual:true});
  route[formKey]=false;route[formKey+"_mat"]="";route[formKey+"_cur"]="";
  save();rerenderKeepScroll();toast("Asignatura añadida ✓");
}
function togglePendienteAprobada(aid,idx){
  if(state.pendientes&&state.pendientes[aid]&&state.pendientes[aid][idx]!=null){
    state.pendientes[aid][idx].aprobada=!state.pendientes[aid][idx].aprobada;
    save();rerenderKeepScroll();
  }
}
function eliminarPendiente(aid,idx){
  if(state.pendientes&&state.pendientes[aid]){
    state.pendientes[aid].splice(idx,1);
    save();rerenderKeepScroll();
  }
}
// ────────────────────────────────────────────────────────────────────────

// ─── GENERADOR DE INFORME DE TUTORÍA ───────────────────────────────────
function generarInforme(a,g,secs,selEvs){
  const inc=s=>!secs||secs.includes(s);
  // Aplicar filtro de evaluaciones
  const esESO2=g.esESO!==false;
  const ieEvs2=esESO2?["I1","I2","I3"].filter(k=>{
    const t=k[1];const ie=state.intereval?.[t];return ie&&ie[a.matricula]!=null;
  }):[];
  const allEvsFull=[...octEvals(g),...ieEvs2];
  const evs=(selEvs&&selEvs.length)?allEvsFull.filter(e=>selEvs.includes(e)):allEvsFull;
  const subs=g.oct?g.oct.subjects.filter(s=>!esExcluida(s.nombre)):[];
  const pends=(state.pendientes&&state.pendientes[a.id])||[];
  const incs=incidenciasDe(a.id);
  const infoPrs=(state.infoProfes&&state.infoProfes[a.id])||[];
  const notaPriv=(state.notasPrivadas&&state.notasPrivadas[a.id])||"";
  const examData=state.notasExamen&&state.notasExamen[a.id];
  const hoy=new Date().toLocaleDateString("es-ES",{day:"2-digit",month:"long",year:"numeric"});

  // ─── Paleta ──────────────────────────────────────────────────────────
  const C={navy:"#1e2d6e",clay:"#8b1a3a",green:"#2e7d32",red:"#c0392b",
            amber:"#c9a227",bg:"#f4f5fb",card:"#fff",line:"#d8daea",
            soft:"#5a5f80",paper2:"#e8eaf6"};

  // ─── Medias por evaluación (para gráfica) ────────────────────────────
  const medias=evs.map(e=>({e,m:octMediaAlumno(g,e,a.matricula)}));
  const mediaActual=medias.filter(x=>x.m!=null).slice(-1)[0]?.m;
  const semaforo=mediaActual==null?"gray":mediaActual>=7?"green":mediaActual>=5?"amber":"red";
  const semaforoColor={green:C.green,amber:C.amber,red:C.red,gray:C.soft}[semaforo];
  const semaforoTxt={green:"Buen rendimiento",amber:"Rendimiento regular",red:"Necesita atención",gray:"Sin datos"}[semaforo];

  // ─── SVG gráfica de evolución ─────────────────────────────────────────
  const pts=medias.filter(x=>x.m!=null);
  let chartSVG="";
  if(pts.length>=2){
    const W=520,H=160,pad={t:20,r:20,b:40,l:40};
    const iW=W-pad.l-pad.r,iH=H-pad.t-pad.b;
    const xStep=iW/(pts.length-1);
    const coords=pts.map((p,i)=>({x:pad.l+i*xStep,y:pad.t+iH-(((p.m-0)/(10-0))*iH)}));
    const path=coords.map((c,i)=>(i===0?`M${c.x},${c.y}`:`L${c.x},${c.y}`)).join(" ");
    const area=`M${coords[0].x},${pad.t+iH} `+coords.map(c=>`L${c.x},${c.y}`).join(" ")+` L${coords[coords.length-1].x},${pad.t+iH} Z`;
    // Ejes Y
    const yLines=[0,2,4,5,6,7,8,10].map(v=>{
      const y=pad.t+iH-((v/10)*iH);
      return `<line x1="${pad.l}" y1="${y}" x2="${pad.l+iW}" y2="${y}" stroke="${v===5?C.clay:C.line}" stroke-width="${v===5?1.5:.6}" stroke-dasharray="${v===5?"4,3":""}"/>
      <text x="${pad.l-6}" y="${y+4}" font-size="9" fill="${C.soft}" text-anchor="end">${v}</text>`;
    }).join("");
    const xLabels=pts.map((p,i)=>{
      const x=pad.l+i*xStep;
      return `<text x="${x}" y="${H-8}" font-size="9" fill="${C.soft}" text-anchor="middle">${evalLabel(p.e)}</text>`;
    }).join("");
    const dots=coords.map((c,i)=>`<circle cx="${c.x}" cy="${c.y}" r="4" fill="${pts[i].m>=5?C.navy:C.clay}" stroke="white" stroke-width="1.5"/>
      <text x="${c.x}" y="${c.y-8}" font-size="9" fill="${pts[i].m>=5?C.navy:C.clay}" text-anchor="middle" font-weight="600">${pts[i].m.toFixed(1)}</text>`).join("");
    chartSVG=`<svg viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" xmlns="http://www.w3.org/2000/svg" style="max-width:100%">
      ${yLines}
      <defs><linearGradient id="ag" x1="0" y1="0" x2="0" y2="1">
        <stop offset="0%" stop-color="${C.navy}" stop-opacity=".15"/>
        <stop offset="100%" stop-color="${C.navy}" stop-opacity="0"/>
      </linearGradient></defs>
      <path d="${area}" fill="url(#ag)"/>
      <path d="${path}" fill="none" stroke="${C.navy}" stroke-width="2.2" stroke-linejoin="round" stroke-linecap="round"/>
      ${dots}${xLabels}
    </svg>`;
  }

  // ─── Tabla de calificaciones ──────────────────────────────────────────
  const evHeaders=evs.map(e=>`<th style="padding:5px 8px;background:${C.navy};color:white;font-size:11px;text-align:center;min-width:58px">${evalLabel(e)}</th>`).join("");
  const subjRows=subs.map(s=>{
    const cells=evs.map(e=>{
      if(/^I[123]$/.test(e)){
        const t=e[1];const ie=(state.intereval?.[t]??{})[a.matricula];
        const origIdx=parseInt(s.id.replace("s",""),10);
        const grade=ie?.grades?.[origIdx]??null;
        if(!grade||grade==="X")return`<td style="padding:5px 8px;text-align:center;color:${C.soft}">—</td>`;
        return`<td style="padding:5px 8px;text-align:center;font-weight:700;color:${grade==="A"?C.green:C.red}">${grade}</td>`;
      }
      const c=octNota(g,e,a.matricula,s.id);
      if(!c)return`<td style="padding:5px 8px;text-align:center;color:${C.soft}">—</td>`;
      const bg=c.n!=null?(c.n>=5?"#e8f5e9":"#ffeaea"):"transparent";
      return`<td style="padding:5px 8px;text-align:center;background:${bg};font-weight:600;color:${c.n!=null?(c.n>=5?C.green:C.red):C.soft}">${c.n!=null?c.n.toFixed(1):(c.lbl||"—")}</td>`;
    }).join("");
    const hasDatos=evs.some(e=>{const c=octNota(g,e,a.matricula,s.id);return c&&(c.n!=null||c.lbl);});
    if(!hasDatos)return"";
    return`<tr><td style="padding:5px 10px;border-right:1px solid ${C.line};font-size:12px">${esc(shortSubj(s.nombre))}</td>${cells}</tr>`;
  }).filter(Boolean).join("");

  // ─── Fila de medias ───────────────────────────────────────────────────
  const mediaRow=evs.map(e=>{
    if(/^I[123]$/.test(e)){
      const t=e[1];const ie=(state.intereval?.[t]??{})[a.matricula];
      const na=ie==null?null:(typeof ie==="number"?ie:ie.na);
      return`<td style="padding:5px 8px;text-align:center;font-weight:700;color:${C.navy}">${na!=null?na+"✗":"—"}</td>`;
    }
    const m=octMediaAlumno(g,e,a.matricula);
    const bg=m!=null?(m>=5?C.navy:C.clay):"transparent";
    const col=m!=null?"white":C.soft;
    return`<td style="padding:5px 8px;text-align:center;background:${bg};color:${col};font-weight:700;border-radius:4px">${m!=null?m.toFixed(2):"—"}</td>`;
  }).join("");

  // ─── Pendientes ───────────────────────────────────────────────────────
  const pendsHTML=!pends.length?"<p style='color:"+C.soft+";font-size:13px'>Sin asignaturas pendientes registradas.</p>":
    `<table style="width:100%;border-collapse:collapse;font-size:13px">
      <thead><tr><th style="padding:5px 10px;background:${C.navy};color:white;text-align:left">Asignatura</th><th style="padding:5px 10px;background:${C.navy};color:white">Curso</th><th style="padding:5px 10px;background:${C.navy};color:white">Estado</th></tr></thead>
      <tbody>${pends.map(p=>`<tr><td style="padding:5px 10px;border-bottom:1px solid ${C.line}">${esc(p.materia)}</td>
        <td style="padding:5px 10px;border-bottom:1px solid ${C.line};color:${C.soft}">${esc(p.curso)}</td>
        <td style="padding:5px 10px;border-bottom:1px solid ${C.line};text-align:center"><span style="padding:2px 10px;border-radius:12px;font-size:11.5px;font-weight:700;background:${p.aprobada?"#e8f5e9":"#ffeaea"};color:${p.aprobada?C.green:C.red}">${p.aprobada?"✓ Superada":"✗ Pendiente"}</span></td>
      </tr>`).join("")}</tbody></table>`;

  // ─── Comentarios profesores ───────────────────────────────────────────
  const profRows=infoPrs.length?infoPrs.map(c=>`<tr>
    <td style="padding:5px 10px;border-bottom:1px solid ${C.line};font-size:12px">${esc(c.materia||"—")}</td>
    <td style="padding:5px 10px;border-bottom:1px solid ${C.line};font-size:11.5px;color:${C.soft}">${TRIM_LBL[c.trim]||c.trim||""}</td>
    <td style="padding:5px 10px;border-bottom:1px solid ${C.line};font-size:12px">${esc(c.obs)}</td>
  </tr>`).join(""):"";

  // ─── Exámenes ─────────────────────────────────────────────────────────
  // Estructura real: examData[ev][subj].exams = [{nombre, nota}]
  let examRows="";
  if(examData){Object.entries(examData).forEach(([ev,subjMap])=>{
    if(!subjMap)return;
    // Solo incluir evaluaciones seleccionadas
    if(selEvs&&selEvs.length&&!selEvs.includes(ev))return;
    Object.entries(subjMap).forEach(([subj,d])=>{
      if(!d||!d.exams||!d.exams.length)return;
      d.exams.forEach(ex=>{
        examRows+=`<tr><td style="padding:5px 10px;border-bottom:1px solid ${C.line};font-size:12px">${esc(subjBonito(subj))}</td>
          <td style="padding:5px 10px;border-bottom:1px solid ${C.line};font-size:11.5px;color:${C.soft}">${evalLabel(ev)}</td>
          <td style="padding:5px 10px;border-bottom:1px solid ${C.line};font-size:12px">${esc(ex.nombre||"")}</td>
          <td style="padding:5px 10px;border-bottom:1px solid ${C.line};text-align:center;font-weight:700;color:${ex.nota>=5?C.green:C.red}">${ex.nota}</td></tr>`;
      });
    });
  });}

  // ─── Incidencias resumen ──────────────────────────────────────────────
  const incCount=incs.length;
  const incTipos={};incs.forEach(i=>{const t=incTipo(i);incTipos[t]=(incTipos[t]||0)+1;});
  const incResumen=Object.entries(incTipos).map(([t,n])=>`<li>${esc(t)}: <strong>${n}</strong></li>`).join("");

  // ─── HTML DEL INFORME ─────────────────────────────────────────────────
  const nombreCompleto=`${a.apellidos}, ${a.nombre}`;
  const html=`<!DOCTYPE html>
<html lang="es"><head><meta charset="UTF-8">
<title>Informe de Tutoría — ${nombreCompleto}</title>
<style>
  *{box-sizing:border-box;margin:0;padding:0}
  body{font-family:Arial,sans-serif;font-size:13px;color:#1a1e3a;background:#fff;line-height:1.5}
  @media print{
    .no-print{display:none!important}
    body{margin:0}
    .page-break{page-break-before:always}
    .panel{break-inside:avoid}
  }
  .header-band{background:${C.navy};color:white;padding:20px 30px;display:flex;justify-content:space-between;align-items:center}
  .header-band h1{font-size:20px;font-weight:700;margin-bottom:3px}
  .header-band .sub{font-size:12px;opacity:.75}
  .body{max-width:900px;margin:0 auto;padding:24px 30px}
  .panel{background:#fff;border:1px solid ${C.line};border-radius:10px;padding:16px 20px;margin-bottom:20px;break-inside:avoid}
  .panel-title{font-size:14px;font-weight:700;color:${C.navy};margin-bottom:12px;padding-bottom:8px;border-bottom:2px solid ${C.paper2};display:flex;align-items:center;gap:7px}
  .kv{display:flex;gap:6px;margin-bottom:5px;font-size:12.5px}
  .kv span{color:${C.soft};min-width:140px}
  .semaforo{display:inline-flex;align-items:center;gap:10px;padding:8px 16px;border-radius:8px;background:${semaforoColor}22;border:1px solid ${semaforoColor}44}
  .dot{width:14px;height:14px;border-radius:50%;background:${semaforoColor}}
  table{width:100%;border-collapse:collapse}
  th{text-align:left;padding:6px 10px;font-size:11px}
  td{vertical-align:top}
  .sect2col{display:grid;grid-template-columns:1fr 1fr;gap:16px}
  .print-btn{position:fixed;top:16px;right:16px;padding:10px 20px;background:${C.navy};color:white;border:none;border-radius:8px;cursor:pointer;font-size:14px;font-weight:600;box-shadow:0 4px 12px rgba(30,45,110,.3)}
</style></head>
<body>
<button class="print-btn no-print" onclick="window.print()">🖨 Imprimir / Guardar PDF</button>
<div class="header-band">
  <div>
    <div class="sub">Colegio Pasteur Arroyomolinos · Informe de Tutoría</div>
    <h1>${esc(nombreCompleto)}</h1>
    <div class="sub">${esc(g.nombre)} · Generado el ${hoy}</div>
  </div>
  <div style="text-align:right">
    <div class="semaforo"><div class="dot"></div><div><div style="font-weight:700;font-size:13px;color:${semaforoColor}">${semaforoTxt}</div>${mediaActual!=null?`<div style="font-size:11px;opacity:.8">Media actual: ${mediaActual.toFixed(2)}</div>`:""}</div></div>
  </div>
</div>
<div class="body">

<!-- Datos del alumno -->
${inc("datos")?`<div class="panel">
  <div class="panel-title">👤 Datos del alumno/a</div>
  <div class="sect2col">
    <div>
      <div class="kv"><span>Nombre completo:</span><strong>${esc(nombreCompleto)}</strong></div>
      <div class="kv"><span>Grupo / Clase:</span><strong>${esc(g.nombre)}</strong></div>
      ${a.matricula?`<div class="kv"><span>Nº Matrícula:</span><strong>${a.matricula}</strong></div>`:""}
    </div>
    <div>
      <div class="kv"><span>Tutor/a:</span><strong>${esc(state.profesor.nombre||"—")}</strong></div>
      <div class="kv"><span>Asignaturas pendientes:</span><strong>${pends.filter(p=>!p.aprobada).length}</strong></div>
      <div class="kv"><span>Incidencias registradas:</span><strong>${incCount}</strong></div>
    </div>
  </div>
</div>`:""}<!-- Calificaciones -->${inc("notas")&&evs.length?`<div class="panel">
  <div class="panel-title">📊 Calificaciones por evaluación</div>
  ${chartSVG?`<div style="margin-bottom:16px;text-align:center">${chartSVG}</div>`:""}
  <table>
    <thead><tr><th style="padding:5px 10px;background:${C.navy};color:white;font-size:11px;text-align:left">Asignatura</th>${evHeaders}</tr></thead>
    <tbody>
      ${subjRows}
      <tr style="border-top:2px solid ${C.navy}">
        <td style="padding:5px 10px;font-weight:700;font-size:11.5px;text-transform:uppercase;letter-spacing:.04em">MEDIA / RESUMEN</td>
        ${mediaRow}
      </tr>
    </tbody>
  </table>
</div>`:""}

<!-- Pendientes -->
${inc("pendientes")?`<div class="panel">
  <div class="panel-title">📚 Asignaturas pendientes de años anteriores</div>
  ${pendsHTML}
</div>`:""}<!-- Comentarios profesores + Exámenes -->
${(inc("profes")||inc("examenes"))?`<div class="sect2col">
  ${inc("profes")&&profRows?`<div class="panel">
    <div class="panel-title">💬 Comentarios de profesores</div>
    <table>
      <thead><tr>
        <th style="background:${C.navy};color:white;padding:5px 10px;font-size:11px">Asignatura</th>
        <th style="background:${C.navy};color:white;padding:5px 10px;font-size:11px">Trim.</th>
        <th style="background:${C.navy};color:white;padding:5px 10px;font-size:11px">Observación</th>
      </tr></thead>
      <tbody>${profRows}</tbody>
    </table>
  </div>`:`<div class="panel"><div class="panel-title">💬 Comentarios de profesores</div><p style="color:${C.soft};font-size:12.5px">Sin comentarios registrados.</p></div>`}
  ${inc("examenes")&&examRows?`<div class="panel">
    <div class="panel-title">✏️ Notas de exámenes</div>
    <table>
      <thead><tr>
        <th style="background:${C.navy};color:white;padding:5px 10px;font-size:11px">Asignatura</th>
        <th style="background:${C.navy};color:white;padding:5px 10px;font-size:11px">Eval.</th>
        <th style="background:${C.navy};color:white;padding:5px 10px;font-size:11px">Examen</th>
        <th style="background:${C.navy};color:white;padding:5px 10px;font-size:11px;text-align:center">Nota</th>
      </tr></thead>
      <tbody>${examRows}</tbody>
    </table>
  </div>`:`<div class="panel"><div class="panel-title">✏️ Notas de exámenes</div><p style="color:${C.soft};font-size:12.5px">Sin notas de exámenes importadas.</p></div>`}
</div>`:""}<!-- Incidencias + Notas del tutor -->
${(inc("incidencias")||inc("tutor"))?`<div class="sect2col">
  ${inc("incidencias")?`<div class="panel">
    <div class="panel-title">⚠️ Incidencias</div>
    ${incCount?`<p style="font-size:12.5px;margin-bottom:8px">Total registradas: <strong>${incCount}</strong></p><ul style="padding-left:18px;font-size:12.5px;line-height:2">${incResumen}</ul>`:
    `<p style="color:${C.soft};font-size:12.5px">Sin incidencias registradas.</p>`}</div>`:""}  ${inc("tutor")?`<div class="panel">
    <div class="panel-title">📝 Notas del tutor</div>
    <p style="font-size:12.5px;white-space:pre-wrap;color:${notaPriv?C.ink:C.soft}">${esc(notaPriv)||"Sin notas privadas."}</p>
  </div>`:""}  
</div>`:""}  
<p style="text-align:center;font-size:10.5px;color:${C.soft};margin-top:8px">Informe generado automáticamente por Aula Pasteur · ${hoy}</p>
</div></body></html>`;

  // Abrir en nueva pestaña
  const blob=new Blob([html],{type:"text/html"});
  const url=URL.createObjectURL(blob);
  window.open(url,"_blank");
  toast("Informe abierto en nueva pestaña — usa Ctrl+P para guardar como PDF");
}
// ────────────────────────────────────────────────────────────────────────

// ─── MODAL DE SELECCIÓN DE SECCIONES DEL INFORME ───────────────────────
function modalInforme(aid, gid){
  const a=state.alumnos.find(x=>x.id===aid);
  const g=state.grupos.find(x=>x.id===gid);
  if(!a||!g)return;
  const SECS=[
    {id:"datos",      lbl:"Datos del alumno/a",         desc:"Nombre, grupo, tutor, matrícula"},
    {id:"notas",      lbl:"Calificaciones y evolución",  desc:"Tabla de notas + gráfica"},
    {id:"pendientes", lbl:"Asignaturas pendientes",      desc:"Materias de cursos anteriores"},
    {id:"examenes",   lbl:"Notas de exámenes",           desc:"Exámenes parciales importados"},
    {id:"profes",     lbl:"Comentarios de profesores",   desc:"Observaciones por asignatura"},
    {id:"incidencias",lbl:"Incidencias",                 desc:"Partes y faltas registradas"},
    {id:"tutor",      lbl:"Notas del tutor",             desc:"Observaciones privadas"},
  ];
  const esESO2=g.esESO!==false;
  const ieEvs2=esESO2?["I1","I2","I3"].filter(k=>{
    const t=k[1];const ie=state.intereval?.[t];return ie&&ie[a.matricula]!=null;
  }):[];
  const allEvs=[...octEvals(g),...ieEvs2];
  // Recuperar selecciones previas
  window._infAid=aid; window._infGid=gid;
  window._infSelSecs=route["infSecs_"+aid]||SECS.map(s=>s.id);
  window._infSelEvs=route["infEvs_"+aid]||[...allEvs];
  window._infAllEvs=allEvs;
  const renderModal=()=>{
    const boxes=SECS.map(s=>{
      const on=window._infSelSecs.includes(s.id);
      return`<label style="display:flex;align-items:flex-start;gap:10px;padding:9px 12px;border-radius:8px;cursor:pointer;transition:background .12s" onmouseover="this.style.background='var(--paper)'" onmouseout="this.style.background=''" onclick="iSecToggleSec('${s.id}');event.preventDefault()">
        <div style="width:16px;height:16px;border-radius:4px;border:2px solid ${on?'var(--navy)':'var(--line-2)'};background:${on?'var(--navy)':'transparent'};flex-shrink:0;margin-top:2px;display:flex;align-items:center;justify-content:center">
          ${on?'<svg viewBox="0 0 10 8" width="10" height="8"><polyline points="1,4 4,7 9,1" stroke="white" stroke-width="1.8" fill="none"/></svg>':""}
        </div>
        <div>
          <div style="font-weight:600;font-size:13px">${esc(s.lbl)}</div>
          <div style="font-size:11px;color:var(--ink-soft)">${esc(s.desc)}</div>
        </div>
      </label>`;
    }).join('<div style="border-top:1px solid var(--line);margin:1px 0"></div>');
    const evBtns=allEvs.map(e=>{
      const on=window._infSelEvs.includes(e);
      return`<button onclick="iSecToggleEv('${e}')" style="padding:6px 12px;border-radius:8px;border:1.5px solid ${on?'var(--navy)':'var(--line-2)'};background:${on?'var(--navy)':'var(--card)'};color:${on?'#fff':'var(--ink)'};font-size:12.5px;font-weight:${on?'700':'400'};cursor:pointer;transition:all .12s">${evalLabel(e)}</button>`;
    }).join("");
    document.getElementById("iModal_body").innerHTML=`
      <p style="font-size:11.5px;font-weight:700;color:var(--ink-soft);text-transform:uppercase;letter-spacing:.05em;margin-bottom:8px">Secciones a incluir</p>
      <div style="border:1px solid var(--line);border-radius:10px;overflow:hidden;margin-bottom:16px">${boxes}</div>
      ${allEvs.length?`<p style="font-size:11.5px;font-weight:700;color:var(--ink-soft);text-transform:uppercase;letter-spacing:.05em;margin-bottom:8px">Evaluaciones / Trimestres</p>
      <div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:16px">${evBtns}
        <button onclick="iEvSelAll(true)" style="padding:6px 10px;border-radius:8px;border:1px dashed var(--line-2);background:transparent;font-size:11.5px;color:var(--ink-soft);cursor:pointer">Todas</button>
        <button onclick="iEvSelAll(false)" style="padding:6px 10px;border-radius:8px;border:1px dashed var(--line-2);background:transparent;font-size:11.5px;color:var(--ink-soft);cursor:pointer">Ninguna</button>
      </div>`:""}
      <div style="display:flex;gap:8px;align-items:center;padding-top:4px;border-top:1px solid var(--line)">
        <button class="btn btn-ghost btn-sm" onclick="iSecSelAll2(true)">Todas secciones</button>
        <button class="btn btn-ghost btn-sm" onclick="iSecSelAll2(false)">Ninguna</button>
        <div style="flex:1"></div>
        <button class="btn btn-ghost" onclick="closeModal()">Cancelar</button>
        <button class="btn btn-primary" onclick="iSecConfirmar()">Generar informe</button>
      </div>`;
  };
  openModalCls(`<div class="modal-head"><h2>📄 Generar informe de tutoría</h2></div>
    <div class="modal-body" id="iModal_body" style="max-height:72vh;overflow-y:auto"></div>`,"");
  renderModal();
  window._iRenderModal=renderModal;
}
function iSecToggleSec(id){
  const arr=window._infSelSecs;
  const i=arr.indexOf(id);
  if(i>=0)arr.splice(i,1);else arr.push(id);
  window._iRenderModal&&window._iRenderModal();
}
function iSecToggleEv(e){
  const arr=window._infSelEvs;
  const i=arr.indexOf(e);
  if(i>=0)arr.splice(i,1);else arr.push(e);
  window._iRenderModal&&window._iRenderModal();
}
function iSecSelAll2(v){
  window._infSelSecs=v?["datos","notas","pendientes","examenes","profes","incidencias","tutor"]:[];
  window._iRenderModal&&window._iRenderModal();
}
function iEvSelAll(v){
  window._infSelEvs=v?[...window._infAllEvs]:[];
  window._iRenderModal&&window._iRenderModal();
}
function iSecConfirmar(){
  const ids=window._infSelSecs||[];
  if(!ids.length){toast("Selecciona al menos una sección");return;}
  const selEvs=window._infSelEvs||window._infAllEvs||[];
  const aid=window._infAid,gid=window._infGid;
  route["infSecs_"+aid]=ids;
  route["infEvs_"+aid]=selEvs;
  closeModal();
  const a=state.alumnos.find(x=>x.id===aid);
  const g=state.grupos.find(x=>x.id===gid);
  if(a&&g)generarInforme(a,g,ids,selEvs);
}
// iSecSelAll reemplazado por iSecSelAll2
// iSecConfirmar reemplazado por versión sin parámetros
// ────────────────────────────────────────────────────────────────────────

// ─── BORRAR EVALUACIÓN ─────────────────────────────────────────────────
function modalBorrarEval(gid){
  const g=state.grupos.find(x=>x.id===gid);
  if(!g)return;
  const evs=g.oct?octEvals(g):[];
  // Interevaluaciones disponibles (solo ESO)
  const als=alumnosDe(gid);
  const esESO=g.esESO!==false;
  const ieDisp=esESO?["1","2","3"].filter(t=>state.intereval&&state.intereval[t]&&als.some(a=>state.intereval[t][a.matricula]!=null)):[];
  if(!evs.length&&!ieDisp.length){toast("No hay evaluaciones ni interevaluaciones importadas");return;}
  const rowEval=(e)=>`
    <div style="display:flex;align-items:center;justify-content:space-between;padding:10px 14px;border-bottom:1px solid var(--line)">
      <div>
        <div style="font-weight:600;font-size:14px">${evalLabel(e)}</div>
        <div style="font-size:11.5px;color:var(--ink-soft)">${Object.keys(g.oct.data[e]||{}).length} alumnos con datos</div>
      </div>
      <button onclick="confirmarBorrarEval('${gid}','${e}')" style="padding:5px 13px;border-radius:8px;border:1.5px solid var(--clay);background:transparent;color:var(--clay);font-size:12.5px;font-weight:600;cursor:pointer" onmouseover="this.style.background='var(--clay)';this.style.color='#fff'" onmouseout="this.style.background='transparent';this.style.color='var(--clay)'">Eliminar</button>
    </div>`;
  const rowIE=(t)=>{
    const n=als.filter(a=>state.intereval[t][a.matricula]!=null).length;
    return`
    <div style="display:flex;align-items:center;justify-content:space-between;padding:10px 14px;border-bottom:1px solid var(--line)">
      <div>
        <div style="font-weight:600;font-size:14px;color:var(--navy)"><span style="font-style:italic">${t}ª Interevaluación</span></div>
        <div style="font-size:11.5px;color:var(--ink-soft)">${n} alumnos con datos</div>
      </div>
      <button onclick="confirmarBorrarIntereval('${gid}','${t}')" style="padding:5px 13px;border-radius:8px;border:1.5px solid var(--clay);background:transparent;color:var(--clay);font-size:12.5px;font-weight:600;cursor:pointer" onmouseover="this.style.background='var(--clay)';this.style.color='#fff'" onmouseout="this.style.background='transparent';this.style.color='var(--clay)'">Eliminar</button>
    </div>`;
  };
  let secciones="";
  if(ieDisp.length){
    secciones+=`<p style="font-size:11.5px;font-weight:700;color:var(--navy);text-transform:uppercase;letter-spacing:.04em;margin:4px 0 6px">Interevaluaciones</p>
      <div style="border:1px solid var(--line);border-radius:10px;overflow:hidden;margin-bottom:14px">${ieDisp.map(rowIE).join("")}</div>`;
  }
  if(evs.length){
    secciones+=`<p style="font-size:11.5px;font-weight:700;color:var(--ink-soft);text-transform:uppercase;letter-spacing:.04em;margin:4px 0 6px">Evaluaciones</p>
      <div style="border:1px solid var(--line);border-radius:10px;overflow:hidden">${evs.map(rowEval).join("")}</div>`;
  }
  openModalCls(`<div class="modal-head"><h2>Borrar evaluación o interevaluación</h2></div>
    <div class="modal-body">
      <p style="font-size:13px;color:var(--ink-soft);margin-bottom:12px">Selecciona qué quieres eliminar. Esta acción no se puede deshacer.</p>
      ${secciones}
    </div>`,"");
}
function confirmarBorrarIntereval(gid,t){
  confirmModal("Eliminar interevaluación",`¿Eliminar la <strong>${t}ª Interevaluación</strong>? Se borrarán todos los datos A/NA de ese trimestre. Esta acción es definitiva.`,()=>{
    const g=state.grupos.find(x=>x.id===gid);
    const als=alumnosDe(gid);
    if(state.intereval&&state.intereval[t]){
      // Borrar solo los alumnos de este grupo
      als.forEach(a=>{if(state.intereval[t][a.matricula]!=null)delete state.intereval[t][a.matricula];});
    }
    save();closeModal();rerenderKeepScroll();
    toast(`${t}ª Interevaluación eliminada ✓`);
  });
}
function confirmarBorrarEval(gid,ev){
  confirmModal("Eliminar evaluación",`¿Eliminar <strong>${evalLabel(ev)}</strong>? Se borrarán todas las notas de esa evaluación. Esta acción es definitiva.`,()=>{
    const g=state.grupos.find(x=>x.id===gid);
    if(!g||!g.oct||!g.oct.data)return;
    delete g.oct.data[ev];
    // Si ya no quedan evaluaciones, limpiar oct
    if(!Object.keys(g.oct.data).some(k=>Object.keys(g.oct.data[k]).length)){
      g.oct=null;
    }
    save();closeModal();rerenderKeepScroll();
    toast(`${evalLabel(ev)} eliminada ✓`);
  });
}
