function modalGenerarParte(gid,aid){
  const g=state.grupos.find(x=>x.id===gid);
  const a=state.alumnos.find(x=>x.id===aid);
  if(!g||!a)return;
  const leves=TIPOS_PARTE.filter(t=>t.nivel==="leve");
  const graves=TIPOS_PARTE.filter(t=>t.nivel==="grave");
  const card=(t)=>`<button onclick="formParte('${t.id}','${gid}','${aid}')" style="display:flex;align-items:center;gap:10px;padding:10px 14px;border-radius:10px;border:1.5px solid var(--line-2);background:var(--card);cursor:pointer;text-align:left;transition:all .12s;width:100%" onmouseover="this.style.borderColor='var(--navy)';this.style.background='var(--paper-2)'" onmouseout="this.style.borderColor='var(--line-2)';this.style.background='var(--card)'">
    <span style="font-size:20px">${t.icono}</span>
    <div>
      <div style="font-weight:600;font-size:13px">${esc(t.lbl.replace(t.icono+" ",""))}</div>
      <div style="font-size:11px;color:var(--ink-soft)">${t.nivel==="leve"?"Falta leve":"Falta grave"}</div>
    </div>
  </button>`;
  openModalCls(`<div class="modal-head"><h2>📄 Generar parte disciplinario</h2></div>
    <div class="modal-body">
      <p style="font-size:12px;color:var(--ink-soft);margin-bottom:12px">Alumno/a: <strong>${esc(a.apellidos+", "+a.nombre)}</strong> · ${esc(g.nombre)}</p>
      <p style="font-size:11.5px;font-weight:700;color:var(--rose);text-transform:uppercase;letter-spacing:.05em;margin-bottom:8px">Faltas graves</p>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-bottom:14px">${graves.map(card).join("")}</div>
      <p style="font-size:11.5px;font-weight:700;color:var(--ink-soft);text-transform:uppercase;letter-spacing:.05em;margin-bottom:8px">Faltas leves</p>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:7px">${leves.map(card).join("")}</div>
    </div>`,"");
}

function formParte(tipoId,gid,aid){
  const g=state.grupos.find(x=>x.id===gid);
  const a=state.alumnos.find(x=>x.id===aid);
  const t=TIPOS_PARTE.find(x=>x.id===tipoId);
  if(!g||!a||!t)return;
  const hoy=new Date();
  const fechaStr=`${String(hoy.getDate()).padStart(2,"0")} de ${["enero","febrero","marzo","abril","mayo","junio","julio","agosto","septiembre","octubre","noviembre","diciembre"][hoy.getMonth()]} de ${hoy.getFullYear()}`;
  const nombreAlumno=(a.apellidos+", "+a.nombre).toUpperCase();
  const subs=(g.oct&&g.oct.subjects||[]).filter(s=>!esExcluida(s.nombre));
  
  // Campos extra según tipo
  const LBL="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.04em;color:var(--ink-soft);display:block;margin-bottom:4px";
  const INP="width:100%;padding:8px 11px;border:1px solid var(--line-2);border-radius:8px;background:#fff;font-size:13px";
  const AREA="width:100%;padding:8px 11px;border:1px solid var(--line-2);border-radius:8px;background:#fff;font-size:13px;resize:vertical";

  const asigSelect=t.asignatura&&subs.length?`
    <div style="margin-bottom:10px"><label style="${LBL}">Asignatura</label>
    <select id="pf_asig" style="${INP}">
      <option value="">Seleccionar...</option>
      ${subs.map(s=>`<option value="${esc(s.nombre)}">${esc(s.nombre)}</option>`).join("")}
    </select></div>`:
    t.asignatura?`<div style="margin-bottom:10px"><label style="${LBL}">Asignatura</label><input id="pf_asig" placeholder="Nombre de la asignatura" style="${INP}"></div>`:"";
  const fechaEfectoField=t.fecha_efecto?`<div style="margin-bottom:10px"><label style="${LBL}">Fecha de efecto de la sanción</label><input id="pf_efecto" value="${fechaStr}" style="${INP}"></div>`:"";

  // Padres desde datos familiares (indexados por matrícula)
  const padresVal=nombresPadresDe(a);

  openModalCls(`<div class="modal-head">
    <h2>${t.icono} ${esc(t.lbl.replace(t.icono+" ",""))}</h2>
    <span style="display:inline-block;padding:2px 10px;border-radius:20px;font-size:11px;font-weight:700;background:${t.nivel==="grave"?"#ffeaea":"#e8eaf6"};color:${t.nivel==="grave"?"var(--rose)":"var(--navy)"}">Falta ${t.nivel}</span>
  </div>
  <div class="modal-body" style="max-height:70vh;overflow-y:auto">
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:10px">
      <div><label style="${LBL}">Profesor/a</label><input id="pf_prof" value="${esc(state.profesor.nombre||"")}" style="${INP}"></div>
      <div><label style="${LBL}">En calidad de</label><input id="pf_rol" value="${esc(t.rol)}" style="${INP}"></div>
      <div><label style="${LBL}">Alumno/a</label><input id="pf_alum" value="${esc(nombreAlumno)}" style="${INP}"></div>
      <div><label style="${LBL}">Grupo</label><input id="pf_grupo" value="${esc(g.nombre.toUpperCase())}" style="${INP}"></div>
    </div>
    ${asigSelect}
    <div style="margin-bottom:10px"><label style="${LBL}">Descripción de los hechos</label>
      <textarea id="pf_hechos" rows="3" style="${AREA}">${esc(t.hechos||"")}</textarea></div>
    <div style="margin-bottom:10px"><label style="${LBL}">El alumno/a manifiesta</label>
      <textarea id="pf_manifest" rows="2" style="${AREA}"></textarea></div>
    <div style="margin-bottom:10px"><label style="${LBL}">Sanción impuesta</label>
      <textarea id="pf_sancion" rows="2" style="${AREA}">${esc(t.sancion||"")}</textarea></div>
    ${fechaEfectoField}
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;margin-bottom:10px">
      <div><label style="${LBL}">Fecha del parte</label><input id="pf_fecha" value="${fechaStr}" style="${INP}"></div>
      <div><label style="${LBL}">Padres / tutores legales</label><input id="pf_padres" value="${esc(padresVal)}" style="${INP}"></div>
    </div>
    <div style="display:flex;gap:8px;justify-content:flex-end;padding-top:8px;border-top:1px solid var(--line)">
      <button class="btn btn-ghost" onclick="modalGenerarParte('${gid}','${aid}')">← Volver</button>
      <button class="btn btn-primary" onclick="prepararParte('${tipoId}','${gid}','${aid}')">📄 Generar Word</button>
    </div>
  </div>`,"");
}

function generarParte(tipoId,gid,aid){
  if(!window.JSZip){toast("Necesitas conexión para cargar el generador de Word");return;}
  const g=state.grupos.find(x=>x.id===gid);
  const a=state.alumnos.find(x=>x.id===aid);
  const t=TIPOS_PARTE.find(x=>x.id===tipoId);
  if(!g||!a||!t)return;
  const v=(id)=>document.getElementById(id)?.value?.trim()||"";
  const datos={
    PROFESOR:v("pf_prof"), ROL:v("pf_rol"),
    ALUMNO:v("pf_alum"), GRUPO:v("pf_grupo"),
    HECHOS:v("pf_hechos"), MANIFESTACION:v("pf_manifest"),
    SANCION:v("pf_sancion"), FECHA:v("pf_fecha"), PADRES:v("pf_padres"),
    ASIGNATURA:v("pf_asig"), FECHA_EFECTO:v("pf_efecto"),
    ARTICULO_LETRA:t.articulo_letra||"",
    ARTICULO_TEXTO:t.articulo_texto||"",
    ARTICULO_REF:t.articulo||"",
    SANCION_LETRA:t.sancion_letra||"prevista en la letra A del apartado 2 del artículo 34",
  };
  // Reemplazar {{ASIGNATURA}} en sanción si hay
  if(datos.ASIGNATURA) datos.SANCION=datos.SANCION.replace("{{ASIGNATURA}}",datos.ASIGNATURA);
  
  const b64=t.nivel==="grave"?PARTE_GRAVE_B64:PARTE_LEVE_B64;
  const bin=atob(b64);
  const bytes=new Uint8Array(bin.length);
  for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);
  JSZip.loadAsync(bytes).then(zip=>{
    return zip.file("word/document.xml").async("string").then(doc=>{
      Object.keys(datos).forEach(k=>{doc=doc.split("{{"+k+"}}").join(xmlEsc(datos[k]));});
      zip.file("word/document.xml",doc);
      return zip.generateAsync({type:"blob",mimeType:"application/vnd.openxmlformats-officedocument.wordprocessingml.document"});
    });
  }).then(blob=>{
    const url=URL.createObjectURL(blob);
    const el=document.createElement("a");
    el.href=url;
    el.download=`Parte ${t.nivel} - ${t.lbl.replace(/[^\w\s]/g,"").trim()} - ${a.apellidos} ${a.nombre}.docx`;
    el.click();URL.revokeObjectURL(url);
    toast("Parte generado ✓");
    // Para tipos con aviso, generar también el aviso
    if(t.aviso) generarAvisoParte(datos,a,g,t);
  }).catch(e=>{console.error(e);toast("Error al generar el parte: "+e.message);});
}

function generarAvisoParte(datos,a,g,t){
  const html=`<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8">
<title>Aviso a familias</title>
<style>body{font-family:Arial,sans-serif;font-size:13px;max-width:700px;margin:40px auto;line-height:1.6;color:#1a1e3a}
h2{text-align:center;font-size:16px;margin-bottom:4px}
.sub{text-align:center;font-size:12px;color:#666;margin-bottom:24px}
.firma{margin-top:40px}.btn-p{position:fixed;top:12px;right:12px;padding:8px 16px;background:#1e2d6e;color:#fff;border:none;border-radius:8px;cursor:pointer;font-size:13px}
@media print{.btn-p{display:none}}</style></head>
<body>
<button class="btn-p" onclick="window.print()">🖨 Imprimir</button>
<h2>COLEGIO PASTEUR ARROYOMOLINOS</h2>
<div class="sub">Aviso a familias · ${datos.FECHA}</div>
<p>Estimado/a <strong>${datos.PADRES||"familia"}</strong>:</p>
<p>Por medio de la presente le comunicamos que su hijo/a <strong>${datos.ALUMNO}</strong>, alumno/a del grupo <strong>${datos.GRUPO}</strong>, ha recibido una sanción por parte del Colegio Pasteur Arroyomolinos por el siguiente motivo:</p>
<blockquote style="border-left:3px solid #1e2d6e;padding:8px 16px;background:#f4f5fb;border-radius:4px;margin:16px 0">
  ${datos.HECHOS.replace(/\n/g,"<br>")}
</blockquote>
<p>La sanción impuesta consiste en:</p>
<blockquote style="border-left:3px solid #8b1a3a;padding:8px 16px;background:#fff0f3;border-radius:4px;margin:16px 0">
  ${datos.SANCION.replace(/\n/g,"<br>")}
</blockquote>
<p>Rogamos que firme y devuelva este documento como confirmación de que ha recibido la presente notificación.</p>
<div class="firma">
  <p>Arroyomolinos (Madrid), a ${datos.FECHA}</p>
  <br><p>El tutor/a: <strong>${datos.PROFESOR}</strong></p>
  <br><br>
  <p>Firma del padre/madre/tutor legal: ___________________________</p>
  <br>
  <p>Fecha de recepción: ___________________________</p>
</div>
</body></html>`;
  const blob=new Blob([html],{type:"text/html"});
  const url=URL.createObjectURL(blob);
  window.open(url,"_blank");
  toast("Aviso para familias abierto en nueva pestaña ✓");
}
