function tabCompararDos(g){
  var als=alumnosDe(g.id);
  if(als.length<2)return "<p style='color:var(--ink-soft)'>Necesitas al menos dos alumnos en el grupo.</p>";
  var allEvs=octEvals(g);
  if(!allEvs.length)return emptyBlock(I.chart,"Sin evaluaciones importadas","Importa una octavilla para poder comparar alumnos.",'<button class="btn btn-primary" onclick="importOctavilla(\'"+g.id+"\')">'+I.upload+"Añadir octavilla</button>");
  var selEv=route.dosCmpEv&&allEvs.includes(route.dosCmpEv)?route.dosCmpEv:allEvs[allEvs.length-1];
  var evBtns=allEvs.map(function(e){return'<button class="'+(e===selEv?"on":"")+('" onclick="setDosCmpEv(\''+e+'\')">')+evalLabel(e)+"</button>";}).join("");
  var evSel='<div style="display:flex;align-items:center;gap:10px;margin-bottom:16px;flex-wrap:wrap"><span style="font-weight:600;font-size:13px">Evaluación:</span><div class="seg">'+evBtns+"</div></div>";
  var aid1=route.cmpAid1||als[0].id;
  var aid2=route.cmpAid2||(als[1]?als[1].id:als[0].id);
  var a1=als.find(function(x){return x.id===aid1;})||als[0];
  var a2=als.find(function(x){return x.id===aid2;})||als[1];
  var subs=(g.oct&&g.oct.subjects||[]).filter(function(s){return !esExcluida(s.nombre);});
  var esESO=g.esESO!==false;
  function getMedia(a){return esESO?mediaAlumnoSinTalleres(g,selEv,a.matricula):octMediaAlumno(g,selEv,a.matricula);}
  var selOptsHtml=function(sel){return als.map(function(a){return'<option value="'+a.id+'" '+( a.id===sel?"selected":"")+'>'+esc(a.apellidos+", "+a.nombre)+"</option>";}).join("");};
  var h='<div style="display:grid;grid-template-columns:1fr auto 1fr;gap:12px;align-items:center;margin-bottom:16px">'
    +'<div><label style="font-size:11px;font-weight:700;color:var(--ink-soft);text-transform:uppercase;letter-spacing:.04em;display:block;margin-bottom:5px">Alumno A</label>'
    +'<select onchange="route.cmpAid1=this.value;rerenderKeepScroll()" style="width:100%;padding:8px 11px;border:1px solid var(--line-2);border-radius:9px;background:#fff;font-size:13px">'
    +selOptsHtml(aid1)+"</select></div>"
    +'<div style="font-weight:800;font-size:18px;color:var(--ink-soft);text-align:center;padding-top:20px">vs</div>'
    +'<div><label style="font-size:11px;font-weight:700;color:var(--ink-soft);text-transform:uppercase;letter-spacing:.04em;display:block;margin-bottom:5px">Alumno B</label>'
    +'<select onchange="route.cmpAid2=this.value;rerenderKeepScroll()" style="width:100%;padding:8px 11px;border:1px solid var(--line-2);border-radius:9px;background:#fff;font-size:13px">'
    +selOptsHtml(aid2)+"</select></div></div>"+evSel;
  if(a1.id===a2.id){h+='<p style="color:var(--ink-soft);text-align:center;padding:20px">Selecciona dos alumnos distintos.</p>';return h;}
  var m1=getMedia(a1),m2=getMedia(a2);
  var delta=m1!=null&&m2!=null?m1-m2:null;
  var ap1=esc(a1.apellidos.split(" ")[0]+", "+a1.nombre.split(" ")[0]);
  var ap2=esc(a2.apellidos.split(" ")[0]+", "+a2.nombre.split(" ")[0]);
  if(delta!=null){
    h+='<div style="display:flex;gap:16px;margin-bottom:16px;flex-wrap:wrap">'
      +'<div style="flex:1;background:var(--paper-2);border:1.5px solid var(--navy);border-radius:10px;padding:10px 14px;text-align:center">'
      +'<div style="font-size:11px;font-weight:700;text-transform:uppercase;color:var(--navy);margin-bottom:4px">'+ap1+"</div>"
      +'<div style="font-size:22px;font-weight:800;color:'+(m1>=5?"var(--green)":"var(--rose)")+'">'+m1.toFixed(2)+"</div></div>"
      +'<div style="display:flex;align-items:center;font-size:13px;color:var(--ink-soft);font-weight:700;padding:0 4px">'
      +Math.abs(delta).toFixed(2)+" pts "+(delta>0?"a favor de A":"a favor de B")+"</div>"
      +'<div style="flex:1;background:var(--paper-2);border:1.5px solid var(--clay);border-radius:10px;padding:10px 14px;text-align:center">'
      +'<div style="font-size:11px;font-weight:700;text-transform:uppercase;color:var(--clay);margin-bottom:4px">'+ap2+"</div>"
      +'<div style="font-size:22px;font-weight:800;color:'+(m2>=5?"var(--green)":"var(--rose)")+'">'+m2.toFixed(2)+"</div></div></div>";
  }
  var subjRows="";
  subs.forEach(function(s){
    var c1=octNota(g,selEv,a1.matricula,s.id);
    var c2=octNota(g,selEv,a2.matricula,s.id);
    if(!c1&&!c2)return;
    var cellHtml=function(c){if(!c)return'<td class="num" style="color:var(--ink-soft)">—</td>';return '<td class="num cmp-cell">'+mediaChip(c.n!=null?c.n:null)+"</td>";};
    var diff=c1&&c2&&c1.n!=null&&c2.n!=null?c1.n-c2.n:null;
    var diffCell=diff!=null?'<td class="num">'+deltaBadge(diff)+"</td>":'<td class="num"></td>';
    subjRows+='<tr><td style="font-size:12.5px">'+esc(shortSubj(s.nombre))+"</td>"+cellHtml(c1)+cellHtml(c2)+diffCell+"</tr>";
  });
  var ap1th='<th class="num" style="color:var(--navy)">'+esc(a1.apellidos.split(" ")[0])+"</th>";
  var ap2th='<th class="num" style="color:var(--clay)">'+esc(a2.apellidos.split(" ")[0])+"</th>";
  var mediaLbl="Media"+(esESO?" (sin tall.)":"");
  var s1=octSuspAlumno(g,selEv,a1.matricula),s2=octSuspAlumno(g,selEv,a2.matricula);
  h+='<div class="tbl-wrap"><table><thead><tr><th style="min-width:120px">Asignatura</th>'+ap1th+ap2th+'<th class="num">Dif.</th></tr></thead><tbody>'
    +subjRows
    +'<tr style="border-top:2px solid var(--line)"><td style="font-weight:700;font-size:11.5px;text-transform:uppercase;letter-spacing:.03em">'+mediaLbl+"</td>"
    +'<td class="num cmp-cell">'+mediaChip(m1)+"</td>"
    +'<td class="num cmp-cell">'+mediaChip(m2)+"</td>"
    +(delta!=null?'<td class="num">'+deltaBadge(delta)+"</td>":'<td></td>')
    +"</tr>"
    +'<tr><td style="font-weight:700;font-size:11.5px;text-transform:uppercase;letter-spacing:.03em">Suspensos</td>'
    +'<td class="num" style="font-weight:600;color:'+(( s1||0)>0?"var(--rose)":"var(--green)")+'">'+( s1??"—")+'</td>'
    +'<td class="num" style="font-weight:600;color:'+(( s2||0)>0?"var(--rose)":"var(--green)")+'">'+( s2??"—")+'</td>'
    +'<td></td></tr></tbody></table></div>';
  return h;
}
