// ─── FIX generarParte: capturar datos en window._parteData ───────────────
function prepararParte(tipoId,gid,aid){
  // Captura todos los valores del formulario EN EL MOMENTO del clic
  const v=(id)=>{const el=document.getElementById(id);return el?el.value.trim():"";};
  // Si el campo padres está vacío, intentar rellenarlo desde familias
  if(!v("pf_padres")){
    const _a2=state.alumnos.find(x=>x.id===aid);
    const _f2=_a2?(state.familias&&(state.familias[_a2.matricula]||state.familias[_a2.id]))||[]:[];
    const _p2=_f2.filter(f=>f.nombre).map(f=>f.nombre).join(" Y ").toUpperCase();
    if(_p2){const el=document.getElementById("pf_padres");if(el)el.value=_p2;}
  }
  window._parteData={
    tipoId,gid,aid,
    PROFESOR:v("pf_prof")||state.profesor.nombre||"", ROL:v("pf_rol"),
    ALUMNO:v("pf_alum"), GRUPO:v("pf_grupo"),
    HECHOS:v("pf_hechos"), MANIFESTACION:v("pf_manifest"),
    SANCION:v("pf_sancion"), FECHA:v("pf_fecha"), PADRES:v("pf_padres"),
    ASIGNATURA:v("pf_asig"), FECHA_EFECTO:v("pf_efecto"),
  };
  generarParteConDatos();
}
function generarParteConDatos(){
  if(!window._parteData){toast("Error: no hay datos del parte");return;}
  if(!window.JSZip){toast("Cargando generador de Word… espera un momento y vuelve a intentarlo");return;}
  const d=window._parteData;
  const t=TIPOS_PARTE.find(x=>x.id===d.tipoId);
  const g=state.grupos.find(x=>x.id===d.gid);
  const a=state.alumnos.find(x=>x.id===d.aid);
  if(!t||!g||!a)return;
  // Obtener padres desde contactosDe (combina state.familias + datos hardcoded)
  const _padresAuto=nombresPadresDe(a);
  const datos={
    PROFESOR:d.PROFESOR||state.profesor.nombre||"",
    ROL:d.ROL||t.rol||"",
    ALUMNO:d.ALUMNO||(a.apellidos+", "+a.nombre).toUpperCase(),
    GRUPO:d.GRUPO||g.nombre.toUpperCase(),
    HECHOS:d.HECHOS||t.hechos||"",
    MANIFESTACION:d.MANIFESTACION||"",
    SANCION:d.SANCION||t.sancion||"",
    FECHA:d.FECHA||new Date().toLocaleDateString("es-ES",{day:"2-digit",month:"long",year:"numeric"}),
    PADRES:d.PADRES||_padresAuto,
    ASIGNATURA:d.ASIGNATURA||"",
    FECHA_EFECTO:d.FECHA_EFECTO||"",
    ARTICULO_LETRA:t.articulo_letra||"",
    ARTICULO_TEXTO:t.articulo_texto||"",
    ARTICULO_REF:t.articulo||"",
    SANCION_LETRA:t.sancion_letra||"prevista en la letra A del apartado 2 del artículo 34",
  };
  if(datos.ASIGNATURA) datos.SANCION=datos.SANCION.replace("{{ASIGNATURA}}",datos.ASIGNATURA);
  const b64=t.nivel==="grave"?PARTE_GRAVE_B64:PARTE_LEVE_B64;
  try{
    const bin=atob(b64);
    const bytes=new Uint8Array(bin.length);
    for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);
    JSZip.loadAsync(bytes).then(function(zip){
      return zip.file("word/document.xml").async("string").then(function(doc){
        Object.keys(datos).forEach(function(k){doc=doc.split("{{"+k+"}}").join(xmlEsc(datos[k]));});
        zip.file("word/document.xml",doc);
        return zip.generateAsync({type:"blob",mimeType:"application/vnd.openxmlformats-officedocument.wordprocessingml.document"});
      });
    }).then(function(blob){
      const url=URL.createObjectURL(blob);
      const el=document.createElement("a");
      el.href=url;
      el.download="Parte "+t.nivel+" - "+a.apellidos+" "+a.nombre+".docx";
      document.body.appendChild(el);el.click();document.body.removeChild(el);
      URL.revokeObjectURL(url);
      toast("Parte generado ✓");
      if(t.aviso) generarAvisoParte(datos,a,g,t);
    }).catch(function(e){console.error(e);toast("Error al generar: "+e.message);});
  }catch(e){console.error(e);toast("Error al preparar el documento: "+e.message);}
}
