// ─── MEDIA SIN TALLERES (calcula desde notas individuales) ─────────────
function mediaAlumnoSinTalleres(g,e,matricula){
  if(!g.oct||!g.oct.subjects||!g.oct.data[e]||!g.oct.data[e][matricula])return null;
  const subs=g.oct.subjects.filter(s=>!esExcluida(s.nombre));
  const notas=subs.map(s=>octNota(g,e,matricula,s.id)).filter(c=>c&&c.n!=null).map(c=>c.n);
  if(!notas.length)return null;
  return notas.reduce((a,b)=>a+b,0)/notas.length;
}
