function setCmpA(e){route.cmpMenu=false;route.cmpA=e;rerenderKeepScroll();}
function setDosCmpEv(e){route.dosCmpEv=e;rerenderKeepScroll();}
function suspDeltaBadge(dSusp){
  if(dSusp==null)return`<span style="color:var(--ink-soft)">—</span>`;
  if(dSusp===0)return`<span class="delta eq" style="font-weight:700">=</span>`;
  if(dSusp<0)return`<span style="color:#1d6fd6;font-weight:700">▼ ${Math.abs(dSusp)}</span>`;
  return`<span style="color:var(--rose);font-weight:700">▲ ${dSusp}</span>`;
}
