function ieBadge(n){
  if(n==null)return`<span style="color:var(--ink-soft)">—</span>`;
  const col=n===0?"var(--green)":"var(--rose)";
  return`<span class="media-chip ${n===0?"m-pass":"m-fail"}" style="font-weight:700">${n}</span>`;
}
function importarInterevaluacion(){
  if(!window.pdfjsLib){toast("No se pudo cargar el lector de PDF (¿sin conexión?)");return}
  const inp=document.createElement("input");inp.type="file";inp.accept="application/pdf,.pdf";
  inp.onchange=e=>{const f=e.target.files[0];if(f)procesarInterevaluacionPDF(f)};inp.click();
}
function procesarInterevaluacionPDF(file){
  openModalCls(`<div class="modal-head"><h2>Leyendo interevaluación…</h2></div><div class="modal-body" style="text-align:center;padding:40px 24px"><div class="spinner"></div><p style="margin-top:16px;color:var(--ink-soft)">Analizando ${esc(file.name)}</p></div>`,"");
  const fr=new FileReader();
  fr.onload=async()=>{
    try{
      const pdf=await pdfjsLib.getDocument({data:new Uint8Array(fr.result)}).promise;
      const secciones=[];
      for(let p=1;p<=pdf.numPages;p++){
        const page=await pdf.getPage(p);
        const vp=page.getViewport({scale:1});
        const tc=await page.getTextContent();
        const items=tc.items.map(it=>({s:it.str.trim(),x:it.transform[4],y:vp.height-it.transform[5]})).filter(it=>it.s);
        const sec=parsearPaginaIntereval(items);
        if(sec&&sec.filas.length)secciones.push(sec);
      }
      if(!secciones.length){closeModal();toast("No encontré datos de alumnos en ese PDF");return}
      window._ieSecciones=secciones;
      mostrarSelectorIntereval();
    }catch(err){console.error(err);closeModal();toast("Error al leer el PDF: "+(err.message||err))}
  };
  fr.readAsArrayBuffer(file);
}
function mostrarSelectorIntereval(){
  const secciones=window._ieSecciones||[];
  if(!secciones.length){closeModal();toast("No se encontraron clases");return;}
  const items=secciones.map((sec,i)=>{
    const prev=sec.filas.slice(0,3).map(f=>`<span style="color:var(--ink-soft)">${esc(f.nombre)}</span> <b>${f.na}</b>`).join(" · ");
    const more=sec.filas.length>3?` <span style="color:var(--ink-soft)">+${sec.filas.length-3} más</span>`:"";
    return`<label style="display:flex;align-items:flex-start;gap:10px;padding:10px 12px;border-radius:8px;cursor:pointer" onmouseover="this.style.background='var(--paper)'" onmouseout="this.style.background=''">
      <input type="checkbox" id="ie_cb_${i}" style="margin-top:3px;accent-color:var(--navy)">
      <div>
        <div style="font-weight:600;font-size:13.5px;margin-bottom:3px">${esc(sec.seccion||"Clase "+(i+1))} <span style="font-weight:400;color:var(--ink-soft);font-size:12px">(${sec.filas.length} alumnos)</span></div>
        <div style="font-size:11.5px;line-height:1.6">${prev}${more}</div>
      </div></label>`;
  }).join('<div style="border-top:1px solid var(--line);margin:2px 0"></div>');
  openModalCls(`<div class="modal-head"><h2>Seleccionar clases a importar</h2></div>
    <div class="modal-body">
      <p style="margin-bottom:10px;font-size:13px;color:var(--ink-soft)">Marca las clases cuyos datos quieres guardar. Las desmarcadas se ignorarán.</p>
      <div style="max-height:380px;overflow-y:auto;border:1px solid var(--line);border-radius:8px;padding:4px">${items}</div>
      <div style="display:flex;gap:8px;margin-top:14px;align-items:center">
        <button class="btn btn-ghost btn-sm" onclick="ieSelTodas(true)">Todas</button>
        <button class="btn btn-ghost btn-sm" onclick="ieSelTodas(false)">Ninguna</button>
        <div style="flex:1"></div>
        <button class="btn btn-ghost" onclick="closeModal()">Cancelar</button>
        <button class="btn btn-primary" onclick="ieConfirmarSeleccion()">Importar seleccionadas</button>
      </div>
    </div>`,"");
}
function ieSelTodas(val){
  (window._ieSecciones||[]).forEach((_,i)=>{const cb=document.getElementById("ie_cb_"+i);if(cb)cb.checked=val;});
}
function ieConfirmarSeleccion(){
  const secciones=window._ieSecciones||[];
  let total=0;
  secciones.forEach((sec,i)=>{
    const cb=document.getElementById("ie_cb_"+i);
    if(!cb||!cb.checked)return;
    sec.filas.forEach(f=>{
      const t=f.trimestre||"1";
      if(!state.intereval[t])state.intereval[t]={};
      state.intereval[t][f.matricula]={na:f.na,gradesByName:f.gradesByName||{},columnas:f.columnas||[]};
      total++;
    });
  });
  if(!total){toast("No hay clases seleccionadas");return;}
  save();closeModal();rerenderKeepScroll();
  toast(`Interevaluación importada: ${total} alumnos ✓`);
}
function parsearPaginaIntereval(items){
  // Sección
  const hdr=items.filter(it=>it.x<160&&it.y>48&&it.y<86&&it.s.length>0).sort((a,b)=>a.y-b.y||a.x-b.x);
  let seccion=null;
  const secLine=items.filter(it=>it.y>=50&&it.y<=62&&it.x<200).sort((a,b)=>a.x-b.x).map(i=>i.s).join(" ");
  const mSec=secLine.match(/Secci[oó]n:\s*(.+)/i);
  if(mSec)seccion=mSec[1].trim();
  // ── 1) Detectar columnas de asignatura (cabeceras arriba, x>280, y<95) ──
  // Agrupar tokens de cabecera por columna (x redondeado a múltiplos cercanos)
  const headTokens=items.filter(it=>it.x>280&&it.y<96);
  // Agrupar por x con tolerancia de 8px
  const colMap=[]; // {x, tokens:[{y,s}]}
  headTokens.forEach(it=>{
    let col=colMap.find(c=>Math.abs(c.x-it.x)<8);
    if(!col){col={x:it.x,tokens:[]};colMap.push(col);}
    col.tokens.push({y:it.y,s:it.s});
  });
  colMap.sort((a,b)=>a.x-b.x);
  const columnas=colMap.map(c=>({
    x:c.x,
    nombre:c.tokens.sort((a,b)=>a.y-b.y).map(t=>t.s).join(" ").replace(/\s+/g," ").trim()
  })).filter(c=>c.nombre.length>0);
  // ── 2) Agrupar items por filas (banda de y) ──
  const bands={};
  items.forEach(it=>{const k=Math.round(it.y/3);(bands[k]=bands[k]||[]).push(it)});
  const filas=[];
  Object.values(bands).forEach(band=>{
    const ws=band.slice().sort((a,b)=>a.x-b.x);
    const words=ws.map(i=>i.s);
    if(words.length<6)return;
    // Anclar: buscar media "0.00"/"0,00"
    const mediaIdx=words.findIndex(w=>/^\d+[.,]\d{2}$/.test(w));
    if(mediaIdx<0)return;
    if(!/^\d{1,3}$/.test(words[0]))return;       // Nº orden
    if(!/^\d{2,5}$/.test(words[1]))return;        // matrícula
    const matricula=words[1];
    const nSuspStr=words[mediaIdx+1]||"";
    if(!/^\d{1,2}$/.test(nSuspStr))return;
    const na=parseInt(nSuspStr,10);
    // Trimestre desde marcador "1I"/"2I"/"3I"
    const evalIdx=words.findIndex((w,i)=>i>=2&&/^\dI$/.test(w));
    const trimestre=evalIdx>=0?words[evalIdx][0]:"1";
    // Nombre: entre matrícula y el marcador de eval (o antes de media)
    const nameEnd=evalIdx>2?evalIdx:mediaIdx;
    const nombre=words.slice(2,nameEnd).join(" ").replace(/\s+,/,",").trim()||"Alumno "+matricula;
    // ── 3) Alinear notas A/NA/X con columnas por proximidad de X ──
    const notasTokens=ws.filter(it=>(it.s==="A"||it.s==="NA"||it.s==="X")&&it.x>280);
    const gradesByName={};
    notasTokens.forEach(nt=>{
      // Encontrar columna más cercana (las notas están ~5px a la izq de la cabecera)
      let best=null,bestD=1e9;
      columnas.forEach(col=>{const d=Math.abs(col.x-nt.x);if(d<bestD){bestD=d;best=col;}});
      if(best&&bestD<14){gradesByName[best.nombre]=nt.s;}
    });
    filas.push({matricula,nombre,na,trimestre,gradesByName,columnas:columnas.map(c=>c.nombre)});
  });
  return{seccion,filas,columnas:columnas.map(c=>c.nombre)};
}
