// ─── HELPERS INTEREVALUACIÓN ───────────────────────────────────────────────
// Evalúa las evaluaciones disponibles para un grupo, entrelazando interevals
// Orden: I1, 1, I2, 2, I3, 3, FPG, F, E
function evalsConIntereval(g){
  const regular=octEvals(g);
  const ie=state.intereval||{};
  const als=alumnosDe(g.id);
  const esESO=g.esESO!==false;
  const ORDER=["I1","1","I2","2","I3","3","FPG","F","E"];
  return ORDER.filter(e=>{
    if(/^I\d$/.test(e)){
      if(!esESO)return false;
      const t=e[1];
      return ie[t]&&als.some(a=>ie[t][a.matricula]!=null);
    }
    return regular.includes(e);
  });
}
// Devuelve el badge A/NA para una asignatura en la interevaluación
function ieGradeCell(g,evalKey,matricula,subjIdx){
  const t=evalKey[1];
  const d=(state.intereval&&state.intereval[t]&&state.intereval[t][matricula])||null;
  const subj=g.oct&&g.oct.subjects&&g.oct.subjects[subjIdx];
  const subjNombre=subj?subj.nombre:null;
  let grade=null;
  if(d){
    if(d.gradesByName&&subjNombre){grade=ieMatchGrade(d.gradesByName,subjNombre);}
    else if(d.grades){try{grade=d.grades[subjIdx];}catch(e){grade=null;}}
  }
  // Celda clicable para editar (ciclo: A → NA → X → A)
  const onClick=`onclick="toggleIeGrade('${matricula}','${t}','${esc(subjNombre||"").replace(/'/g,"\\\\'")}',this)"`;
  if(!grade||grade==="X"){
    return`<td class="num gcell"><button class="gbtn" ${onClick} title="Pulsa para marcar A/NA" style="color:var(--ink-soft)">—</button></td>`;
  }
  const col=grade==="A"?"var(--green)":"var(--rose)";
  return`<td class="num gcell"><button class="gbtn" ${onClick} title="Pulsa para cambiar"><span style="color:${col};font-weight:700">${grade}</span></button></td>`;
}
// Alterna A→NA→X→A para una asignatura concreta de un alumno en una interevaluación
function toggleIeGrade(matricula,t,subjNombre,btn){
  if(!state.intereval[t])state.intereval[t]={};
  if(!state.intereval[t][matricula])state.intereval[t][matricula]={na:0,gradesByName:{}};
  const d=state.intereval[t][matricula];
  if(!d.gradesByName)d.gradesByName={};
  // Encontrar la clave existente (por match normalizado) o usar el nombre tal cual
  const norm=s=>String(s).toUpperCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^A-Z0-9]/g,"");
  const target=norm(subjNombre);
  let key=null;
  for(const k in d.gradesByName){if(norm(k)===target||norm(k).includes(target)||target.includes(norm(k))){key=k;break;}}
  if(!key)key=subjNombre;
  const actual=d.gradesByName[key]||"X";
  const next={A:"NA",NA:"X",X:"A"}[actual]||"A";
  d.gradesByName[key]=next;
  // Recalcular nº NA (sin talleres) para guardar en d.na
  const g=state.grupos.find(gr=>alumnosDe(gr.id).some(a=>String(a.matricula)===String(matricula)));
  if(g&&g.oct&&g.oct.subjects){
    let na=0;
    g.oct.subjects.forEach(s=>{if(esExcluida(s.nombre))return;if(ieMatchGrade(d.gradesByName,s.nombre)==="NA")na++;});
    d.na=na;
  }
  save();rerenderKeepScroll();
}
// Empareja un nombre de asignatura con la clave correspondiente en gradesByName (normalizado)
function ieMatchGrade(gradesByName,subjNombre){
  const norm=s=>String(s).toUpperCase().normalize("NFD").replace(/[\u0300-\u036f]/g,"").replace(/[^A-Z0-9]/g,"");
  const target=norm(subjNombre);
  // Match exacto normalizado
  for(const k in gradesByName){if(norm(k)===target)return gradesByName[k];}
  // Match por inclusión (uno contiene al otro)
  for(const k in gradesByName){const nk=norm(k);if(nk&&(nk.includes(target)||target.includes(nk)))return gradesByName[k];}
  return null;
}
// Devuelve celda de resumen de interevaluación (nº NA) para tabAlumnosTut
function ieResumenCell(g,evalKey,matricula){
  const t=evalKey[1];
  const d=(state.intereval&&state.intereval[t]&&state.intereval[t][matricula])||null;
  if(!d)return`<td class="num" style="color:var(--ink-soft)">—</td>`;
  let na=0;
  if(d.gradesByName&&g.oct&&g.oct.subjects){
    // Contar NA en asignaturas no excluidas (sin talleres)
    g.oct.subjects.forEach(s=>{
      if(esExcluida(s.nombre))return;
      const grade=ieMatchGrade(d.gradesByName,s.nombre);
      if(grade==="NA")na++;
    });
  }else if(d.grades&&g.oct&&g.oct.subjects){
    g.oct.subjects.forEach((s,i)=>{
      if(esExcluida(s.nombre))return;
      if(d.grades[i]==="NA")na++;
    });
  }else{
    na=d.na!=null?d.na:0;
  }
  return`<td class="num">${ieBadge(na)}</td>`;
}
