// ─── NOMBRES DE PADRES PARA PARTES ─────────────────────────────────────────
// Usa contactosDe() que combina state.familias + FAMILIAS_1BACHA hardcoded.
// Los nombres vienen como "APELLIDOS, NOMBRE"; los devolvemos tal cual en mayúsculas,
// unidos por " Y " (ej: "ÁLVAREZ FERNÁNDEZ, EDUARDO Y AREÁN VALLE, NÚRIA").
function nombresPadresDe(alumno){
  if(!alumno||!alumno.matricula)return "";
  let lista=[];
  try{ lista=contactosDe(alumno.matricula)||[]; }catch(e){ lista=[]; }
  const nombres=lista.filter(c=>c&&c.nombre&&c.nombre.trim()).map(c=>c.nombre.trim().toUpperCase());
  return nombres.join(" Y ");
}
