// ─── COMEDOR ────────────────────────────────────────────────────────────
const MESES_COMEDOR=["Septiembre","Octubre","Noviembre","Diciembre","Enero","Febrero","Marzo","Abril","Mayo","Junio"];
function mesComedorActual(){
  const m=new Date().getMonth(); // 0=ene
  const map={8:"Septiembre",9:"Octubre",10:"Noviembre",11:"Diciembre",0:"Enero",1:"Febrero",2:"Marzo",3:"Abril",4:"Mayo",5:"Junio"};
  return map[m]||"Septiembre";
}
function tabComedor(g){
  if(!state.comedor)state.comedor={};
  if(!state.comedor[g.id])state.comedor[g.id]={};
  const datosGrupo=state.comedor[g.id];
  const mesSel=route.comedorMes||mesComedorActual();
  // Estructura: state.comedor[mes] = [{nombre, seccion}]
  const registros=(datosGrupo[mesSel]||[]);
  // Selector de mes
  const mesBtns=MESES_COMEDOR.map(m=>{
    const n=(datosGrupo[m]||[]).length;
    return`<button class="${m===mesSel?"on":""}" onclick="route.comedorMes='${m}';rerenderKeepScroll()" style="position:relative">${m}${n?` <span style="opacity:.7;font-size:11px">(${n})</span>`:""}</button>`;
  }).join("");
  let h=`<div style="display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:16px;flex-wrap:wrap">
    <h2 style="margin:0">🍽 Comedor</h2>
    <div style="display:flex;gap:8px">
      <button class="btn btn-ghost btn-sm" onclick="importarComedor('${g.id}')">${I.upload}Importar Excel</button>
      ${registros.length?`<button class="btn btn-ghost btn-sm" onclick="exportarComedor('${g.id}')">⬇ Exportar</button>`:""}
      ${registros.length?`<button class="btn btn-ghost btn-sm" onclick="borrarComedorMes('${g.id}','${mesSel}')" style="color:var(--clay)"><svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2" width="15" height="15"><polyline points="5,5 15,5"/><rect x="6" y="7" width="8" height="9" rx="1"/><line x1="8" y1="9" x2="8" y2="14"/><line x1="12" y1="9" x2="12" y2="14"/></svg>Borrar ${mesSel}</button>`:""}
    </div>
  </div>`;
  h+=`<div class="seg seg-wrap" style="margin-bottom:18px">${mesBtns}</div>`;

  if(!registros.length){
    h+=emptyBlock(I.users,"Sin registros para "+mesSel,"Importa el Excel del comedor de este mes (columnas «Usuario» y «Sección») para ver el recuento de alumnos.",`<button class="btn btn-primary" onclick="importarComedor('${g.id}')">${I.upload}Importar Excel</button>`);
    return h;
  }

  // Agrupar por sección
  const porSeccion={};
  registros.forEach(r=>{
    const sec=r.seccion||"Sin clase";
    (porSeccion[sec]=porSeccion[sec]||[]).push(r);
  });
  const secciones=Object.keys(porSeccion).sort((a,b)=>a.localeCompare(b,'es',{numeric:true}));

  // Resumen total
  h+=`<div style="display:flex;gap:14px;flex-wrap:wrap;margin-bottom:18px">
    <div style="flex:1;min-width:140px;background:var(--paper-2);border:1px solid var(--line);border-radius:12px;padding:14px 18px">
      <div style="font-size:12px;color:var(--ink-soft);text-transform:uppercase;letter-spacing:.05em">Total comensales</div>
      <div style="font-size:30px;font-weight:800;line-height:1.1;color:var(--navy)">${registros.length}</div>
      <div style="font-size:12px;color:var(--ink-soft)">${mesSel}</div>
    </div>
  </div>`;

  // Recuento por clase
  h+=`<div class="panel" style="margin-bottom:18px"><h3 style="margin:0 0 12px">Recuento por clase</h3>
    <table style="width:100%;border-collapse:collapse;font-size:13.5px">
      <thead><tr style="border-bottom:2px solid var(--line)"><th style="text-align:left;padding:6px 10px">Clase</th><th style="text-align:right;padding:6px 10px">Comensales</th></tr></thead>
      <tbody>${secciones.map(sec=>`<tr style="border-bottom:1px solid var(--line)">
        <td style="padding:7px 10px">${esc(sec)}</td>
        <td style="padding:7px 10px;text-align:right;font-weight:700;color:var(--navy)">${porSeccion[sec].length}</td>
      </tr>`).join("")}
      <tr style="border-top:2px solid var(--navy)"><td style="padding:7px 10px;font-weight:700;text-transform:uppercase;font-size:12px">Total</td>
        <td style="padding:7px 10px;text-align:right;font-weight:800;color:var(--navy);font-size:15px">${registros.length}</td></tr>
      </tbody>
    </table>
  </div>`;

  // Listado por clase (acordeón)
  h+=`<div style="display:flex;flex-direction:column;gap:8px">`;
  secciones.forEach(sec=>{
    const alumnos=porSeccion[sec].slice().sort((a,b)=>a.nombre.localeCompare(b.nombre,'es'));
    const keyEx="comedorOpen_"+mesSel+"_"+sec.replace(/\W/g,"");
    const open=!!route[keyEx];
    h+=`<div style="border:1px solid var(--line-2);border-radius:10px;overflow:hidden">
      <div style="display:flex;align-items:center;gap:10px;padding:10px 13px;cursor:pointer;background:var(--paper-2)" onclick="route['${keyEx}']=!route['${keyEx}'];rerenderKeepScroll()">
        <svg viewBox="0 0 16 16" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2" style="flex-shrink:0;transition:transform .15s;transform:rotate(${open?90:0}deg)"><polyline points="5,3 11,8 5,13"/></svg>
        <span style="font-weight:600;font-size:14px;flex:1">${esc(sec)}</span>
        <span style="font-size:13px;color:var(--navy);font-weight:700">${alumnos.length}</span>
      </div>
      ${open?`<div style="padding:8px 13px;border-top:1px solid var(--line)">
        <ol style="margin:0;padding-left:24px;font-size:13px;line-height:1.9">
          ${alumnos.map(a=>`<li>${esc(a.nombre)}</li>`).join("")}
        </ol>
      </div>`:""}
    </div>`;
  });
  h+=`</div>`;
  return h;
}
function importarComedor(gid){
  if(!window.XLSX){toast("No se pudo cargar el lector de Excel (¿sin conexión?)");return;}
  const inp=document.createElement("input");inp.type="file";inp.accept=".xlsx,.xls,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet";
  inp.onchange=e=>{const f=e.target.files[0];if(f)procesarComedorExcel(f,gid);};inp.click();
}
function procesarComedorExcel(file,gid){
  openModalCls(`<div class="modal-head"><h2>Leyendo comedor…</h2></div><div class="modal-body" style="text-align:center;padding:40px 24px"><div class="spinner"></div></div>`,"");
  const fr=new FileReader();
  fr.onload=()=>{
    try{
      const wb=XLSX.read(new Uint8Array(fr.result),{type:"array"});
      const ws=wb.Sheets[wb.SheetNames[0]];
      const rows=XLSX.utils.sheet_to_json(ws,{header:1,defval:"",raw:false});
      // Detectar columnas Usuario y Sección
      let headerRow=0,colU=0,colS=1;
      for(let i=0;i<Math.min(5,rows.length);i++){
        const r=rows[i].map(c=>String(c).toLowerCase());
        const iu=r.findIndex(c=>/usuario|alumno|nombre/.test(c));
        const is=r.findIndex(c=>/secci|clase|grupo|curso/.test(c));
        if(iu>=0&&is>=0){headerRow=i;colU=iu;colS=is;break;}
      }
      const registros=[];
      for(let i=headerRow+1;i<rows.length;i++){
        const nombre=String(rows[i][colU]||"").trim();
        let seccion=String(rows[i][colS]||"").trim();
        if(!nombre)continue;
        // Limpiar sección: "1º E.S.O. - A Colegio Concertado..." → "1º E.S.O. - A"
        seccion=seccion.replace(/colegio\s+conc\w*.*/i,"").replace(/secci[oó]n:?/i,"").trim();
        // Descartar filas de cabecera residual (nombre "Usuario" o sección vacía/no-clase)
        if(/^usuario$/i.test(nombre))continue;
        registros.push({nombre,seccion:seccion||"Sin clase"});
      }
      if(!registros.length){closeModal();toast("No encontré datos. El Excel debe tener columnas «Usuario» y «Sección»");return;}
      window._comedorRecords=registros;
      window._comedorGid=gid;
      mostrarSelectorMesComedor();
    }catch(err){console.error(err);closeModal();toast("Error al leer el Excel: "+(err.message||err));}
  };
  fr.readAsArrayBuffer(file);
}
function mostrarSelectorMesComedor(){
  const recs=window._comedorRecords||[];
  // Agrupar por sección para mostrar las clases detectadas
  const porSec={};
  recs.forEach(r=>{const s=r.seccion||"Sin clase";(porSec[s]=porSec[s]||[]).push(r);});
  const secciones=Object.keys(porSec).sort((a,b)=>a.localeCompare(b,'es',{numeric:true}));
  const opts=MESES_COMEDOR.map(m=>`<option value="${m}" ${m===mesComedorActual()?"selected":""}>${m}</option>`).join("");
  const clasesBoxes=secciones.map((sec,i)=>`
    <label style="display:flex;align-items:center;gap:10px;padding:8px 12px;border-radius:8px;cursor:pointer" onmouseover="this.style.background='var(--paper)'" onmouseout="this.style.background=''">
      <input type="checkbox" id="comedorCls_${i}" data-sec="${esc(sec)}" style="accent-color:var(--navy)">
      <span style="flex:1;font-size:13.5px;font-weight:500">${esc(sec)}</span>
      <span style="font-size:12px;color:var(--ink-soft)">${porSec[sec].length} comensales</span>
    </label>`).join('<div style="border-top:1px solid var(--line);margin:1px 0"></div>');
  openModalCls(`<div class="modal-head"><h2>Importar comedor</h2></div>
    <div class="modal-body" style="max-height:72vh;overflow-y:auto">
      <p style="font-size:13.5px;margin-bottom:14px">Se han leído <strong>${recs.length} comensales</strong> en <strong>${secciones.length} clases</strong>.</p>
      <label style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.04em;color:var(--ink-soft);display:block;margin-bottom:5px">Mes</label>
      <select id="comedorMesSel" style="width:100%;padding:9px 12px;border:1px solid var(--line-2);border-radius:9px;background:#fff;font-size:14px;margin-bottom:16px">${opts}</select>
      <p style="font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.04em;color:var(--ink-soft);margin-bottom:6px">Clases a importar</p>
      <p style="font-size:12px;color:var(--ink-soft);margin-bottom:8px">Marca solo las clases de tu tutoría:</p>
      <div style="border:1px solid var(--line);border-radius:10px;overflow:hidden;margin-bottom:10px">${clasesBoxes}</div>
      <div style="display:flex;gap:8px;align-items:center;margin-bottom:16px">
        <button class="btn btn-ghost btn-sm" onclick="comedorSelTodas(true)">Todas</button>
        <button class="btn btn-ghost btn-sm" onclick="comedorSelTodas(false)">Ninguna</button>
      </div>
      <div style="display:flex;gap:8px;justify-content:flex-end">
        <button class="btn btn-ghost" onclick="closeModal()">Cancelar</button>
        <button class="btn btn-primary" onclick="confirmarComedor()">Guardar</button>
      </div>
    </div>`,"");
}
function comedorSelTodas(val){
  const recs=window._comedorRecords||[];
  const porSec={};recs.forEach(r=>{const s=r.seccion||"Sin clase";porSec[s]=1;});
  Object.keys(porSec).forEach((_,i)=>{const cb=document.getElementById("comedorCls_"+i);if(cb)cb.checked=val;});
}
function confirmarComedor(){
  const recs=window._comedorRecords||[];
  const gid=window._comedorGid;
  const mes=document.getElementById("comedorMesSel")?.value||mesComedorActual();
  const seleccionadas=new Set();
  document.querySelectorAll('[id^="comedorCls_"]').forEach(cb=>{
    if(cb.checked)seleccionadas.add(cb.getAttribute("data-sec"));
  });
  if(!seleccionadas.size){toast("Marca al menos una clase");return;}
  const filtrados=recs.filter(r=>seleccionadas.has(r.seccion||"Sin clase"));
  if(!state.comedor)state.comedor={};
  if(!state.comedor[gid])state.comedor[gid]={};
  state.comedor[gid][mes]=filtrados;
  route.comedorMes=mes;
  save();closeModal();rerenderKeepScroll();
  toast(`Comedor de ${mes}: ${filtrados.length} comensales guardados ✓`);
}
function exportarComedor(gid){
  const mes=route.comedorMes||mesComedorActual();
  const recs=(state.comedor&&state.comedor[gid]&&state.comedor[gid][mes])||[];
  if(!recs.length){toast("No hay datos para exportar");return;}
  // Agrupar por sección para el recuento
  const porSec={};recs.forEach(r=>{const s=r.seccion||"Sin clase";(porSec[s]=porSec[s]||[]).push(r);});
  let csv="Usuario,Sección\n";
  recs.forEach(r=>{csv+=`"${r.nombre}","${r.seccion}"\n`;});
  csv+="\nRecuento por clase,\n";
  Object.keys(porSec).sort().forEach(s=>{csv+=`"${s}",${porSec[s].length}\n`;});
  csv+=`"TOTAL",${recs.length}\n`;
  const blob=new Blob(["\ufeff"+csv],{type:"text/csv;charset=utf-8"});
  const url=URL.createObjectURL(blob);const el=document.createElement("a");
  el.href=url;el.download=`Comedor ${mes}.csv`;el.click();URL.revokeObjectURL(url);
  toast("Exportado ✓");
}
function borrarComedorMes(gid,mes){
  const n=(state.comedor&&state.comedor[gid]&&state.comedor[gid][mes]||[]).length;
  confirmModal("Borrar comedor",`¿Eliminar los <strong>${n} comensales</strong> registrados en <strong>${mes}</strong>? Esta acción no se puede deshacer.`,()=>{
    if(state.comedor&&state.comedor[gid])delete state.comedor[gid][mes];
    save();closeModal();rerenderKeepScroll();
    toast(`Datos de comedor de ${mes} eliminados ✓`);
  });
}
